fn t2_bundle_overlay_rows(
    service_rows: &[T2ServiceSelectionRow],
    bundle_rows: &[NationalSegmentBundleRow],
    overlay_rows: &[GameT2ServiceOverlayRow],
) -> Vec<T2BundleOverlayRow> {
    let registry = route_network::BundleRegistry::new(
        bundle_rows
            .iter()
            .map(segment_bundle_from_national_row)
            .collect(),
    );
    let overlay_by_class = overlay_rows
        .iter()
        .map(|row| (row.service_class.clone(), row))
        .collect::<std::collections::BTreeMap<_, _>>();

    service_rows
        .iter()
        .map(|service| {
            let route_bundles = registry.by_route_label(&service.route);
            let bundle = route_bundles.first().copied();
            let overlay = overlay_by_class.get(&service.beck_service_class);
            let service_class = if service.beck_service_class.trim().is_empty() {
                "unclassified".to_string()
            } else {
                service.beck_service_class.clone()
            };
            let (binding_status, next_artifact, validation_status) = match (bundle, overlay) {
                (Some(_), _) if service_class == "unclassified" => (
                    "service-class-held-known",
                    "data/game/t2-service-overlays.csv",
                    "review",
                ),
                (Some(bundle), Some(_))
                    if bundle
                        .validation_statuses
                        .iter()
                        .all(|status| status == "pass") =>
                {
                    ("bundle-bound", "data/game/t2-scenario-hooks.csv", "pass")
                }
                (Some(_), Some(_)) => (
                    "bundle-bound-review",
                    "data/national-segment-bundles.csv",
                    "review",
                ),
                (None, Some(_)) => (
                    "bundle-binding-pending",
                    "data/national-segment-bundles.csv",
                    "review",
                ),
                (_, None) => (
                    "service-class-overlay-pending",
                    "data/game/t2-service-overlays.csv",
                    "review",
                ),
            };
            T2BundleOverlayRow {
                tier: service.tier.clone(),
                region_id: service.region_id.clone(),
                route: service.route.clone(),
                segment_bundle_id: bundle
                    .map(|bundle| bundle.segment_bundle_id.clone())
                    .unwrap_or_default(),
                bundle_status: bundle
                    .map(|bundle| bundle.bundle_status.as_str().to_string())
                    .unwrap_or_else(|| "missing-bundle".to_string()),
                service_class,
                map_id: overlay.map(|row| row.map_id.clone()).unwrap_or_default(),
                scenario_hook: overlay
                    .map(|row| row.scenario_hook.clone())
                    .unwrap_or_default(),
                incident_lever: overlay
                    .map(|row| row.incident_lever.clone())
                    .unwrap_or_default(),
                upgrade_lever: overlay
                    .map(|row| row.upgrade_lever.clone())
                    .unwrap_or_default(),
                restitch_lever: overlay
                    .map(|row| row.restitch_lever.clone())
                    .unwrap_or_default(),
                release_gate: overlay
                    .map(|row| row.release_gate.clone())
                    .unwrap_or_default(),
                pavement_debt_cost_m: service.pavement_debt_cost_m,
                pavement_debt_class: service.pavement_debt_class.clone(),
                pavement_debt_basis: service.pavement_debt_basis.clone(),
                source_artifacts:
                    "data/t2-service-selection.csv;data/national-segment-bundles.csv;data/game/t2-service-overlays.csv"
                        .to_string(),
                binding_status: binding_status.to_string(),
                next_artifact: next_artifact.to_string(),
                validation_status: validation_status.to_string(),
            }
        })
        .collect()
}

fn segment_bundle_from_national_row(
    row: &NationalSegmentBundleRow,
) -> route_network::SegmentBundle {
    route_network::SegmentBundle {
        segment_bundle_id: row.segment_bundle_id.clone(),
        bundle_role: row.bundle_role.clone(),
        member_segment_ids: semicolon_values(&row.member_segment_ids),
        stitch_group_ids: semicolon_values(&row.stitch_group_ids),
        current_tiers: semicolon_values(&row.current_tiers),
        current_zone_ids: semicolon_values(&row.current_zone_ids),
        route_labels: semicolon_values(&row.route_labels),
        state_scope: semicolon_values(&row.state_scope),
        evidence_state_scope: semicolon_values(&row.evidence_state_scope),
        geometry_state_scope: semicolon_values(&row.geometry_state_scope),
        bundle_aliases: semicolon_values(&row.bundle_aliases),
        source_artifacts: semicolon_values(&row.source_artifacts),
        registry_actions: Vec::new(),
        validation_statuses: vec![row.validation_status.clone()],
        bundle_status: route_network::BundleStatus::from_label(&row.bundle_status),
    }
}

fn write_t2_bundle_overlays(path: &Path, rows: &[T2BundleOverlayRow]) -> Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("creating {}", parent.display()))?;
    }
    let mut writer = csv::Writer::from_path(path)?;
    for row in rows {
        writer.serialize(row)?;
    }
    writer.flush()?;
    Ok(())
}

fn print_t2_bundle_overlay_summary(output: &Path, rows: &[T2BundleOverlayRow]) {
    let mut counts = std::collections::BTreeMap::<&str, usize>::new();
    for row in rows {
        *counts.entry(row.binding_status.as_str()).or_default() += 1;
    }
    println!(
        "  wrote {} T2 bundle overlay rows to {}",
        rows.len(),
        output.display()
    );
    for (status, count) in counts {
        println!("  {status}: {count}");
    }
}

fn t2_bundle_overlay_gate_failures(rows: &[T2BundleOverlayRow]) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T2 bundle overlay rows emitted".to_string());
        return failures;
    }
    for row in rows {
        if row.route.trim().is_empty()
            || row.service_class.trim().is_empty()
            || row.binding_status.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.source_artifacts.trim().is_empty()
        {
            failures.push(format!(
                "{} has incomplete bundle overlay fields",
                row.route
            ));
        }
        if !matches!(
            row.binding_status.as_str(),
            "bundle-bound"
                | "bundle-bound-review"
                | "bundle-binding-pending"
                | "service-class-overlay-pending"
                | "service-class-held-known"
        ) {
            failures.push(format!(
                "{} has unknown binding status {}",
                row.route, row.binding_status
            ));
        }
        if row.binding_status.starts_with("bundle-bound")
            && !row.segment_bundle_id.starts_with("US.HWYBUNDLE.")
        {
            failures.push(format!(
                "{} claims bundle binding without a bundle id",
                row.route
            ));
        }
        if row.binding_status == "bundle-bound" && row.validation_status != "pass" {
            failures.push(format!("{} bound bundle did not pass", row.route));
        }
        if row.pavement_debt_cost_m < 0.0 {
            failures.push(format!("{} has negative pavement debt cost", row.route));
        }
        if row.pavement_debt_cost_m > 0.0
            && (row.pavement_debt_class.trim().is_empty()
                || row.pavement_debt_basis.trim().is_empty())
        {
            failures.push(format!(
                "{} has pavement debt cost without debt class and basis",
                row.route
            ));
        }
        if !matches!(row.validation_status.as_str(), "pass" | "review") {
            failures.push(format!(
                "{} has invalid validation status {}",
                row.route, row.validation_status
            ));
        }
    }
    failures
}

fn tier_segment_candidate_rows(
    graph: &route_network::HighwayGraph,
    t1_rows: &[T1LineSelectorInputRow],
    t2_rows: &[T2ServiceSelectionRow],
    repair_rows: &[T2BundleRepairQueueRow],
    route_family_rows: &[T2RouteFamilySplitRow],
) -> Vec<TierSegmentCandidateRow> {
    let split_service_families = route_family_rows
        .iter()
        .filter(|row| row.family_action == "split-numbered-service-family")
        .map(|row| canonical_route_key(&row.route))
        .collect::<std::collections::BTreeSet<_>>();
    let mut service_rows = Vec::<(&str, &str, String, String, String, String)>::new();
    for row in t1_rows.iter().filter(|row| row.selected) {
        service_rows.push((
            "T1",
            "t1-line-selector",
            "national".to_string(),
            row.route.clone(),
            row.selected_stops.clone(),
            "selected T1 SLA promise route; decompose into graph segment members before bundle stitching"
                .to_string(),
        ));
    }
    for row in t2_rows.iter().filter(|row| {
        matches!(
            row.selection_action.as_str(),
            "keep-service-column" | "parent-region-review" | "source-needed"
        )
    }) {
        service_rows.push((
            "T2",
            "t2-service-selection",
            row.region_id.clone(),
            row.route.clone(),
            row.parent_trunks.clone(),
            format!(
                "{}; {}; {}",
                row.beck_service_class, row.qualification_basis, row.selection_basis
            ),
        ));
    }
    for row in repair_rows
        .iter()
        .filter(|row| row.next_artifact == "data/national-segment-bundles.csv")
    {
        service_rows.push((
            "T2",
            "t2-bundle-repair-queue",
            "bundle-repair".to_string(),
            row.route.clone(),
            row.repair_class.clone(),
            format!(
                "{}; {}; {}",
                row.bundle_status, row.bundle_action, row.repair_action
            ),
        ));
    }

    let mut rows = Vec::new();
    for (tier, source_selector, region_id, route, selector_basis, action_basis) in service_rows {
        let route_key = normalise_designation(&route);
        let split_by_state =
            tier == "T2" && split_service_families.contains(&canonical_route_key(&route_key));
        let mut edges = graph.route_edges(&route_key).to_vec();
        edges.sort_by_key(|edge_idx| graph.graph[*edge_idx].id);
        let edge_count = edges.len();
        for (edge_sequence, edge_idx) in edges.into_iter().enumerate() {
            let edge = &graph.graph[edge_idx];
            let edge_state = route_network::infer_edge_state(edge);
            let bundle_scope = if split_by_state {
                edge_state.clone()
            } else {
                String::new()
            };
            let segment_bundle_id =
                tier_candidate_bundle_id(tier, &region_id, &route_key, &bundle_scope);
            let stitch_group_id =
                tier_candidate_stitch_group_id(tier, &region_id, &route_key, &bundle_scope);
            rows.push(TierSegmentCandidateRow {
                tier: tier.to_string(),
                source_selector: source_selector.to_string(),
                region_id: region_id.clone(),
                route: route_key.clone(),
                edge_id: edge.id,
                edge_sequence: edge_sequence + 1,
                national_segment_id: tier_candidate_segment_id(edge),
                segment_bundle_id: segment_bundle_id.clone(),
                stitch_group_id: stitch_group_id.clone(),
                member_role: if edge_count > 1 {
                    "stitched-member".to_string()
                } else {
                    "single-member-candidate".to_string()
                },
                state: edge_state,
                length_miles: rounded_score(edge.length_miles),
                aadt: edge
                    .aadt
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| "unknown".to_string()),
                lane_count: edge
                    .lane_count
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| "unknown".to_string()),
                route_aliases: tier_candidate_aliases(tier, &region_id, &route_key, &bundle_scope),
                selector_basis: selector_basis.clone(),
                candidate_action: action_basis.clone(),
                next_artifact: "data/national-segment-registry.csv".to_string(),
                validation_status: "review".to_string(),
            });
        }
    }
    rows.sort_by(|a, b| {
        a.tier
            .cmp(&b.tier)
            .then_with(|| a.region_id.cmp(&b.region_id))
            .then_with(|| a.route.cmp(&b.route))
            .then_with(|| a.edge_sequence.cmp(&b.edge_sequence))
            .then_with(|| a.edge_id.cmp(&b.edge_id))
    });
    rows
}

fn tier_candidate_segment_id(edge: &route_network::HighwayEdge) -> String {
    let first = edge.geometry.0.first().copied();
    let last = edge.geometry.0.last().copied();
    let geometry_key = match (first, last) {
        (Some(first), Some(last)) => {
            format!("{:.5},{:.5}->{:.5},{:.5}", first.x, first.y, last.x, last.y)
        }
        _ => "missing-geometry".to_string(),
    };
    format!(
        "US.HWYSEG.{:016X}",
        stable_segment_hash(&format!(
            "edge|{}|{}|{}|{:.3}",
            edge.route_id, edge.state, geometry_key, edge.length_miles
        ))
    )
}

fn tier_candidate_bundle_id(
    tier: &str,
    region_id: &str,
    route: &str,
    bundle_scope: &str,
) -> String {
    let identity = if bundle_scope.trim().is_empty() {
        format!("candidate-bundle|{tier}|{region_id}|{route}")
    } else {
        format!("candidate-bundle|{tier}|{region_id}|{route}|{bundle_scope}")
    };
    format!("US.HWYBUNDLE.{:016X}", stable_segment_hash(&identity))
}

fn tier_candidate_stitch_group_id(
    tier: &str,
    region_id: &str,
    route: &str,
    bundle_scope: &str,
) -> String {
    let identity = if bundle_scope.trim().is_empty() {
        format!("candidate-stitch|{tier}|{region_id}|{route}")
    } else {
        format!("candidate-stitch|{tier}|{region_id}|{route}|{bundle_scope}")
    };
    format!("US.HWYSTITCH.{:016X}", stable_segment_hash(&identity))
}

fn tier_candidate_aliases(tier: &str, region_id: &str, route: &str, bundle_scope: &str) -> String {
    let mut aliases = vec![
        format!("current-tier:{tier}"),
        format!("current-zone:{region_id}"),
        format!("route:{route}"),
        format!("route-label:{route}"),
        "layer:segment-candidate".to_string(),
    ];
    if !bundle_scope.trim().is_empty() {
        aliases.push(format!("route-family-scope:{bundle_scope}"));
    }
    aliases.join(";")
}

