fn tier_pavement_docket_gate_failures(
    rows: &[TierPavementDocketRow],
    segment_rows: &[TierSegmentCandidateRow],
) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no tier pavement docket rows emitted".to_string());
        return failures;
    }
    if rows.len() != segment_rows.len() {
        failures.push(format!(
            "pavement docket row count {} does not match segment candidate count {}",
            rows.len(),
            segment_rows.len()
        ));
    }

    let mut seen = std::collections::BTreeSet::<(String, u64)>::new();
    for row in rows {
        if row.tier.trim().is_empty()
            || row.route.trim().is_empty()
            || row.segment_bundle_id.trim().is_empty()
            || row.stitch_group_id.trim().is_empty()
            || row.national_segment_id.trim().is_empty()
            || row.state.trim().is_empty()
            || row.iri_m_per_km.trim().is_empty()
            || row.max_iri_m_per_km.trim().is_empty()
            || row.pavement_status.trim().is_empty()
            || row.repair_action.trim().is_empty()
            || row.source_contract.trim().is_empty()
            || row.next_artifact.trim().is_empty()
        {
            failures.push(format!(
                "{}:{} edge {} has incomplete pavement docket fields",
                row.tier, row.route, row.edge_id
            ));
        }
        if !row.segment_bundle_id.starts_with("US.HWYBUNDLE.") {
            failures.push(format!("{} is not a bundle id", row.segment_bundle_id));
        }
        if !row.national_segment_id.starts_with("US.HWYSEG.") {
            failures.push(format!("{} is not a segment id", row.national_segment_id));
        }
        if !seen.insert((row.segment_bundle_id.clone(), row.edge_id)) {
            failures.push(format!(
                "{} repeats pavement edge {}",
                row.segment_bundle_id, row.edge_id
            ));
        }
        if !matches!(
            row.pavement_status.as_str(),
            "pavement-floor-pass"
                | "pavement-repair-required"
                | "pavement-source-needed"
                | "missing-tier-standard"
                | "missing-graph-edge"
        ) {
            failures.push(format!(
                "{}:{} edge {} has unknown pavement status {}",
                row.tier, row.route, row.edge_id, row.pavement_status
            ));
        }
        if !matches!(row.validation_status.as_str(), "pass" | "review") {
            failures.push(format!(
                "{}:{} edge {} has invalid validation status {}",
                row.tier, row.route, row.edge_id, row.validation_status
            ));
        }
        if row.validation_status == "pass" && row.pavement_status != "pavement-floor-pass" {
            failures.push(format!(
                "{}:{} edge {} passes without a pavement-floor-pass status",
                row.tier, row.route, row.edge_id
            ));
        }
    }
    failures
}

#[derive(Default)]
struct TierPavementSourceGapBuilder {
    tier: String,
    route: String,
    region_id: String,
    segment_bundle_id: String,
    stitch_group_id: String,
    member_count: usize,
    blocker_count: usize,
    blocker_statuses: std::collections::BTreeSet<String>,
    affected_states: std::collections::BTreeSet<String>,
    affected_edge_ids: std::collections::BTreeSet<u64>,
    source_contracts: std::collections::BTreeSet<String>,
}

fn tier_pavement_source_gap_rows(
    graph: Option<&route_network::HighwayGraph>,
    docket_rows: &[TierPavementDocketRow],
) -> Vec<TierPavementSourceGapRow> {
    let mut builders = std::collections::BTreeMap::<String, TierPavementSourceGapBuilder>::new();

    for row in docket_rows {
        let builder = builders
            .entry(row.segment_bundle_id.clone())
            .or_insert_with(|| TierPavementSourceGapBuilder {
                tier: row.tier.clone(),
                route: row.route.clone(),
                region_id: row.region_id.clone(),
                segment_bundle_id: row.segment_bundle_id.clone(),
                stitch_group_id: row.stitch_group_id.clone(),
                ..Default::default()
            });
        builder.member_count += 1;
        if row.validation_status == "review" || row.pavement_status != "pavement-floor-pass" {
            builder.blocker_count += 1;
            builder.blocker_statuses.insert(row.pavement_status.clone());
            if !row.state.trim().is_empty() {
                builder.affected_states.insert(row.state.clone());
            }
            builder.affected_edge_ids.insert(row.edge_id);
            if !row.source_contract.trim().is_empty() {
                builder.source_contracts.insert(row.source_contract.clone());
            }
        }
    }

    builders
        .into_values()
        .filter(|builder| builder.blocker_count > 0)
        .map(|builder| {
            let blocker_statuses = join_string_set(&builder.blocker_statuses);
            let affected_states = if builder.affected_states.is_empty() {
                tier_pavement_route_state_scope(graph, &builder.route)
            } else {
                join_string_set(&builder.affected_states)
            };
            let affected_edge_ids = builder
                .affected_edge_ids
                .iter()
                .map(|edge_id| edge_id.to_string())
                .collect::<Vec<_>>()
                .join(";");
            let source_contract = join_string_set(&builder.source_contracts);
            let (source_action, next_artifact, optimizer_effect, validation_status) =
                tier_pavement_source_gap_decision(&blocker_statuses);
            TierPavementSourceGapRow {
                tier: builder.tier,
                route: builder.route,
                region_id: builder.region_id,
                segment_bundle_id: builder.segment_bundle_id,
                stitch_group_id: builder.stitch_group_id,
                member_count: builder.member_count,
                blocker_count: builder.blocker_count,
                blocker_statuses,
                affected_states,
                affected_edge_ids,
                source_contract,
                source_action: source_action.to_string(),
                next_artifact: next_artifact.to_string(),
                optimizer_effect: optimizer_effect.to_string(),
                validation_status: validation_status.to_string(),
            }
        })
        .collect()
}

fn tier_pavement_route_state_scope(
    graph: Option<&route_network::HighwayGraph>,
    route: &str,
) -> String {
    graph
        .and_then(|graph| route_network::aggregate_corridor(graph, route))
        .map(|corridor| corridor.states.join(";"))
        .unwrap_or_default()
}

fn tier_pavement_source_gap_decision(
    blocker_statuses: &str,
) -> (&'static str, &'static str, &'static str, &'static str) {
    if blocker_statuses.contains("pavement-repair-required") {
        return (
            "price pavement repair debt for failing member segments",
            "data/tier-pavement-docket.csv",
            "bundle remains service-addressable while pavement repair debt is priced and paid before SLA or transit readiness claims",
            "review",
        );
    }
    if blocker_statuses.contains("pavement-source-needed") {
        return (
            "price pavement evidence debt for affected member edges",
            "data/standards-l1-inventory.csv",
            "bundle remains service-addressable while pavement source debt is acquired and converted to pass or repair debt",
            "review",
        );
    }
    (
        "review pavement debt status",
        "data/tier-pavement-docket.csv",
        "bundle remains service-addressable while pavement debt is classified",
        "review",
    )
}

