fn t3_zone_access_obligation_rows(
    intake_rows: &[T3T4PressureIntakeRow],
    atlas_rows: &[MapAtlasRow],
) -> Vec<T3ZoneAccessObligationRow> {
    #[derive(Default)]
    struct ObligationAggregate {
        routes: std::collections::BTreeSet<String>,
        intake_classes: std::collections::BTreeSet<String>,
    }

    let t3_maps = t3_zone_map_ids(atlas_rows);
    let mut aggregates = std::collections::BTreeMap::<(String, String), ObligationAggregate>::new();

    for row in intake_rows {
        let Some((zone_id, _zone_name)) = t3_zone_for_route(&row.route) else {
            continue;
        };
        if !t3_maps.contains(zone_id) {
            continue;
        }
        let obligation_class = t3_obligation_class_for_intake(&row.intake_class);
        let aggregate = aggregates
            .entry((zone_id.to_string(), obligation_class.to_string()))
            .or_default();
        aggregate.routes.insert(row.route.clone());
        aggregate.intake_classes.insert(row.intake_class.clone());
    }

    let mut rows = aggregates
        .into_iter()
        .filter_map(|((zone_id, obligation_class), aggregate)| {
            let (_zone_id, zone_name) = t3_zone_catalog_entry(&zone_id)?;
            let (access_target, horizon, next_artifact, optimizer_effect) =
                t3_zone_obligation_contract(&obligation_class);
            Some(T3ZoneAccessObligationRow {
                zone_id: zone_id.clone(),
                zone_name: zone_name.to_string(),
                obligation_class: obligation_class.clone(),
                access_target: access_target.to_string(),
                promise_horizon_hours: horizon,
                source_route_count: aggregate.routes.len(),
                candidate_routes: aggregate
                    .routes
                    .iter()
                    .cloned()
                    .collect::<Vec<_>>()
                    .join(";"),
                source_intake_classes: aggregate
                    .intake_classes
                    .iter()
                    .cloned()
                    .collect::<Vec<_>>()
                    .join(";"),
                map_id: zone_id,
                next_artifact: next_artifact.to_string(),
                optimizer_effect: optimizer_effect.to_string(),
                validation_status: "review".to_string(),
            })
        })
        .collect::<Vec<_>>();

    rows.sort_by(|a, b| {
        a.zone_id
            .cmp(&b.zone_id)
            .then_with(|| a.promise_horizon_hours.cmp(&b.promise_horizon_hours))
            .then_with(|| a.obligation_class.cmp(&b.obligation_class))
    });
    rows
}

fn t3_zone_map_ids(atlas_rows: &[MapAtlasRow]) -> std::collections::BTreeSet<String> {
    atlas_rows
        .iter()
        .filter(|row| row.map_type == "t3-zone")
        .map(|row| row.map_id.clone())
        .collect()
}

fn t3_zone_for_route(route: &str) -> Option<(&'static str, &'static str)> {
    let key = canonical_route_key(route);
    let zone_id = match key.as_str() {
        "I71" | "I72" | "I74" | "I75" | "I93" | "I96" | "I115" | "I129" | "I176" | "I180"
        | "I190" | "I196" | "I220" | "I235" | "I264" | "I270" | "I271" | "I275" | "I276"
        | "I279" | "I280" | "I294" | "I390" | "I465" | "I471" | "I478" | "I480" | "I496"
        | "I675" | "I691" | "I696" | "I990" | "US7" | "US10" | "US15" | "US22" | "US31"
        | "US35" | "US40" | "US41" | "US42" | "US74" | "US75" | "US223" | "US224" | "US250" => {
            "t3-great-lakes"
        }
        "I16" | "I22" | "I24" | "I37" | "I57" | "I59" | "I65" | "I85" | "I140" | "I175"
        | "I185" | "I464" | "I795" | "US17" | "US45E" | "US45W" | "US74E" | "US80" | "US82"
        | "US84" | "US90Z" | "US119" | "US278" | "US301" => "t3-southeast",
        "I2" | "I10" | "I19" | "I37W" | "I45" | "I69E" | "I110" | "I410" | "I510" | "I610"
        | "US69" | "US77" | "US83" | "US90" | "US96" | "US281" => "t3-texas-border",
        "I8" | "I15" | "I25" | "I70" | "I80" | "I135" | "I205" | "I215" | "I225" | "I335"
        | "I680" | "I705" | "I880" | "US2" | "US6" | "US14" | "US26" | "US76" | "US87" | "US95"
        | "US287" => "t3-mountain-west",
        "I30" | "I40" | "I44" | "I49" | "I55" | "I169" | "I181" | "I240" | "I255" | "I277"
        | "I295" | "I630" | "I635" | "I664" | "I759" | "I840" | "US24" | "US66" | "US69S"
        | "US70" | "US71" | "US167" | "US270" | "US421" => "t3-mid-south",
        _ => return None,
    };
    t3_zone_catalog_entry(zone_id)
}

fn t3_zone_catalog_entry(zone_id: &str) -> Option<(&'static str, &'static str)> {
    match zone_id {
        "t3-great-lakes" => Some(("t3-great-lakes", "Great Lakes / Ohio Valley")),
        "t3-southeast" => Some(("t3-southeast", "Southeast / Appalachia")),
        "t3-texas-border" => Some(("t3-texas-border", "Texas Border / Gulf Access")),
        "t3-mountain-west" => Some(("t3-mountain-west", "Mountain West / Interior Coverage")),
        "t3-mid-south" => Some(("t3-mid-south", "Mid-South / Delta / Ozarks")),
        _ => None,
    }
}

fn t3_obligation_class_for_intake(intake_class: &str) -> &'static str {
    match intake_class {
        "bubble-up-t2-review" => "regional-upgrade-review",
        "t4-local-intake" => "terminal-local-access",
        _ => "regional-feeder-access",
    }
}

fn t3_zone_obligation_contract(
    obligation_class: &str,
) -> (&'static str, u8, &'static str, &'static str) {
    match obligation_class {
        "regional-upgrade-review" => (
            "prove T2 contact and regional service value before upgrade",
            24,
            "data/t2-bubble-up-review.csv",
            "keeps lower-tier upgrade pressure attached to zone maps before any T2 reopening",
        ),
        "terminal-local-access" => (
            "select T4 terminal/local access chain inside the zone",
            1,
            "data/t4-terminal-access-columns.csv",
            "turns local pressure into terminal access columns instead of national promotion",
        ),
        _ => (
            "select T3 feeder/contact chain inside the zone",
            6,
            "data/t3-zone-route-columns.csv",
            "turns lower-tier pressure into regional feeder obligations for zone maps",
        ),
    }
}

fn write_t3_zone_access_obligations(path: &Path, rows: &[T3ZoneAccessObligationRow]) -> Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("creating {}", parent.display()))?;
    }
    let mut writer = csv::Writer::from_path(path)?;
    for row in rows {
        writer.serialize(row)?;
    }
    writer.flush()?;
    Ok(())
}

fn print_t3_zone_access_obligation_summary(output: &Path, rows: &[T3ZoneAccessObligationRow]) {
    let mut by_zone = std::collections::BTreeMap::<&str, usize>::new();
    let mut by_class = std::collections::BTreeMap::<&str, usize>::new();
    for row in rows {
        *by_zone.entry(row.zone_id.as_str()).or_default() += 1;
        *by_class.entry(row.obligation_class.as_str()).or_default() += 1;
    }

    println!(
        "  wrote {} T3 zone access obligation rows to {}",
        rows.len(),
        output.display()
    );
    for (zone, count) in by_zone {
        println!("  {zone}: {count}");
    }
    for (class, count) in by_class {
        println!("  {class}: {count}");
    }
}

fn t3_zone_access_obligation_gate_failures(
    rows: &[T3ZoneAccessObligationRow],
    atlas_rows: &[MapAtlasRow],
) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T3 zone access obligations emitted".to_string());
        return failures;
    }

    let t3_maps = t3_zone_map_ids(atlas_rows);
    let covered_zones = rows
        .iter()
        .map(|row| row.zone_id.clone())
        .collect::<std::collections::BTreeSet<_>>();
    for map_id in &t3_maps {
        if !covered_zones.contains(map_id) {
            failures.push(format!("{map_id} has no access obligation row"));
        }
    }

    for row in rows {
        if row.zone_id.trim().is_empty()
            || row.zone_name.trim().is_empty()
            || row.obligation_class.trim().is_empty()
            || row.access_target.trim().is_empty()
            || row.source_route_count == 0
            || row.candidate_routes.trim().is_empty()
            || row.source_intake_classes.trim().is_empty()
            || row.map_id.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.optimizer_effect.trim().is_empty()
        {
            failures.push(format!(
                "{} {} has incomplete access obligation fields",
                row.zone_id, row.obligation_class
            ));
        }
        if row.zone_id != row.map_id {
            failures.push(format!(
                "{} {} is detached from map id {}",
                row.zone_id, row.obligation_class, row.map_id
            ));
        }
        if !t3_maps.contains(&row.map_id) {
            failures.push(format!(
                "{} {} references unknown T3 map {}",
                row.zone_id, row.obligation_class, row.map_id
            ));
        }
        if !matches!(row.validation_status.as_str(), "pass" | "review") {
            failures.push(format!(
                "{} {} has invalid validation status {}",
                row.zone_id, row.obligation_class, row.validation_status
            ));
        }
    }
    failures
}

fn load_t3_zone_access_obligations(path: &Path) -> Result<Vec<T3ZoneAccessObligationRow>> {
    if !path.exists() {
        return Ok(Vec::new());
    }
    let mut reader = csv::Reader::from_path(path)?;
    let mut rows = Vec::new();
    for row in reader.deserialize() {
        rows.push(row?);
    }
    Ok(rows)
}

fn t3_zone_route_column_rows(
    obligations: &[T3ZoneAccessObligationRow],
    intake_rows: &[T3T4PressureIntakeRow],
    constraint_budget_index: &OptimizerConstraintBudgetIndex,
) -> Vec<T3ZoneRouteColumnRow> {
    let intake_by_route = intake_rows
        .iter()
        .map(|row| (canonical_route_key(&row.route), row))
        .collect::<std::collections::BTreeMap<_, _>>();

    let mut rows = Vec::new();
    for obligation in obligations {
        for route in semicolon_values(&obligation.candidate_routes) {
            let intake = intake_by_route.get(&canonical_route_key(&route));
            let current_tier = intake
                .map(|row| row.current_tier.clone())
                .unwrap_or_else(|| "unknown".to_string());
            let current_score = intake.map(|row| row.current_score).unwrap_or(0.0);
            let (
                hard_blocker_count,
                claim_blocker_count,
                constraint_debt_cost_m,
                lifecycle_debt_cost_m,
                constraint_penalty_score,
                top_constraint_classes,
                constraint_ledger_artifact,
            ) = constraint_budget_for_candidate(&route, "", constraint_budget_index);
            let constraint_adjusted_score = current_score - constraint_penalty_score;
            let (
                column_decision,
                zone_role,
                contact_requirement,
                map_treatment,
                basis,
                next_artifact,
                effect,
                status,
            ) = t3_zone_route_column_decision(obligation, &route, current_score, intake.is_some());
            rows.push(T3ZoneRouteColumnRow {
                zone_id: obligation.zone_id.clone(),
                zone_name: obligation.zone_name.clone(),
                obligation_class: obligation.obligation_class.clone(),
                route,
                current_tier,
                current_score,
                constraint_adjusted_score,
                hard_blocker_count,
                claim_blocker_count,
                constraint_debt_cost_m,
                lifecycle_debt_cost_m,
                constraint_penalty_score,
                top_constraint_classes,
                constraint_ledger_artifact,
                promise_horizon_hours: obligation.promise_horizon_hours,
                column_decision: column_decision.to_string(),
                zone_role: zone_role.to_string(),
                contact_requirement: contact_requirement.to_string(),
                map_treatment: map_treatment.to_string(),
                selection_basis: basis.to_string(),
                source_obligation: obligation.access_target.clone(),
                next_artifact: next_artifact.to_string(),
                optimizer_effect: effect.to_string(),
                validation_status: status.to_string(),
            });
        }
    }

    rows.sort_by(|a, b| {
        a.zone_id
            .cmp(&b.zone_id)
            .then_with(|| a.obligation_class.cmp(&b.obligation_class))
            .then_with(|| b.current_score.total_cmp(&a.current_score))
            .then_with(|| a.route.cmp(&b.route))
    });
    rows
}

fn semicolon_values(value: &str) -> Vec<String> {
    value
        .split(';')
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .map(ToString::to_string)
        .collect()
}

fn t3_zone_route_column_decision(
    obligation: &T3ZoneAccessObligationRow,
    _route: &str,
    current_score: f64,
    has_intake: bool,
) -> (
    &'static str,
    &'static str,
    &'static str,
    &'static str,
    &'static str,
    &'static str,
    &'static str,
    &'static str,
) {
    if !has_intake {
        return (
            "source-needed",
            "unscored-candidate",
            "intake-score-required",
            "hide-from-map",
            "candidate route is missing from T3/T4 pressure intake",
            "data/t3-t4-pressure-intake.csv",
            "cannot select a T3 zone route without a scored intake row",
            "review",
        );
    }

    match obligation.obligation_class.as_str() {
        "regional-upgrade-review" => (
            "upward-review",
            "possible-t2-upgrade",
            "t2-contact-witness-required",
            "show-as-review-connector",
            "24h obligation is a T2 reopening review, not a T3 feeder selection",
            "data/t2-bubble-up-review.csv",
            "keeps near-threshold routes visible while blocking direct promotion",
            "review",
        ),
        "terminal-local-access" => (
            "t4-access-review",
            "terminal-local-access",
            "terminal-obligation-required",
            "show-as-local-access-candidate",
            "1h obligation belongs to terminal/local access columns",
            "data/t4-terminal-access-columns.csv",
            "passes local access pressure to the T4 selector",
            "review",
        ),
        _ if current_score >= T3_THRESHOLD => (
            "selected",
            "regional-feeder",
            "higher-tier-or-regional-contact-required",
            "render-as-zone-column",
            "score meets T3 threshold and satisfies a 6h feeder obligation",
            "data/t3-zone-map-diagnostics.csv",
            "feeds the T3 zone map and stop-column selector",
            "pass",
        ),
        _ => (
            "review",
            "below-threshold-feeder-candidate",
            "score-or-terminal-evidence-required",
            "show-as-held-zone-candidate",
            "candidate is below T3 threshold for a 6h feeder obligation",
            "data/t3-t4-access-gaps.csv",
            "holds weak feeder pressure for access-gap review instead of selecting it",
            "review",
        ),
    }
}

