fn print_t3_zone_route_column_summary(output: &Path, rows: &[T3ZoneRouteColumnRow]) {
    let mut by_decision = std::collections::BTreeMap::<&str, usize>::new();
    let mut by_zone = std::collections::BTreeMap::<&str, usize>::new();
    for row in rows {
        *by_decision.entry(row.column_decision.as_str()).or_default() += 1;
        *by_zone.entry(row.zone_id.as_str()).or_default() += 1;
    }
    println!(
        "  wrote {} T3 zone route column rows to {}",
        rows.len(),
        output.display()
    );
    for (zone, count) in by_zone {
        println!("  {zone}: {count}");
    }
    for (decision, count) in by_decision {
        println!("  {decision}: {count}");
    }
}

fn t3_zone_route_column_gate_failures(
    rows: &[T3ZoneRouteColumnRow],
    obligations: &[T3ZoneAccessObligationRow],
) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T3 zone route columns emitted".to_string());
        return failures;
    }

    let mut seen = std::collections::BTreeSet::<(String, String, String)>::new();
    for row in rows {
        if row.zone_id.trim().is_empty()
            || row.zone_name.trim().is_empty()
            || row.obligation_class.trim().is_empty()
            || row.route.trim().is_empty()
            || row.column_decision.trim().is_empty()
            || row.zone_role.trim().is_empty()
            || row.contact_requirement.trim().is_empty()
            || row.map_treatment.trim().is_empty()
            || row.selection_basis.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.optimizer_effect.trim().is_empty()
        {
            failures.push(format!(
                "{} {} {} has incomplete route-column fields",
                row.zone_id, row.obligation_class, row.route
            ));
        }
        if !seen.insert((
            row.zone_id.clone(),
            row.obligation_class.clone(),
            canonical_route_key(&row.route),
        )) {
            failures.push(format!(
                "{} {} {} has duplicate route-column row",
                row.zone_id, row.obligation_class, row.route
            ));
        }
        if row.column_decision == "selected" && row.current_score < T3_THRESHOLD {
            failures.push(format!(
                "{} {} selected below T3 threshold",
                row.zone_id, row.route
            ));
        }
        if row.constraint_debt_cost_m < 0.0 {
            failures.push(format!(
                "{} {} has negative constraint debt cost",
                row.zone_id, row.route
            ));
        }
        if row.lifecycle_debt_cost_m < 0.0 {
            failures.push(format!(
                "{} {} has negative lifecycle debt cost",
                row.zone_id, row.route
            ));
        }
        if row.constraint_penalty_score < 0.0 {
            failures.push(format!(
                "{} {} has negative constraint penalty",
                row.zone_id, row.route
            ));
        }
        if (row.hard_blocker_count > 0
            || row.claim_blocker_count > 0
            || row.constraint_debt_cost_m > 0.0
            || row.lifecycle_debt_cost_m > 0.0
            || row.constraint_penalty_score > 0.0)
            && (row.top_constraint_classes.trim().is_empty()
                || row.constraint_ledger_artifact.trim().is_empty())
        {
            failures.push(format!(
                "{} {} has constraint pressure without class summary and ledger artifact",
                row.zone_id, row.route
            ));
        }
        if !matches!(row.validation_status.as_str(), "pass" | "review") {
            failures.push(format!(
                "{} {} has invalid validation status {}",
                row.zone_id, row.route, row.validation_status
            ));
        }
    }

    for obligation in obligations
        .iter()
        .filter(|row| row.obligation_class == "regional-feeder-access")
    {
        let selected_count = rows
            .iter()
            .filter(|row| {
                row.zone_id == obligation.zone_id
                    && row.obligation_class == obligation.obligation_class
                    && row.column_decision == "selected"
            })
            .count();
        if selected_count == 0 {
            failures.push(format!(
                "{} regional-feeder-access has no selected route column",
                obligation.zone_id
            ));
        }
    }

    failures
}

fn t4_terminal_access_column_rows(
    intake_rows: &[T3T4PressureIntakeRow],
    constraint_budget_index: &OptimizerConstraintBudgetIndex,
) -> Vec<T4TerminalAccessColumnRow> {
    let mut rows = intake_rows
        .iter()
        .filter(|row| row.current_tier == "T4" || row.intake_class == "t4-local-intake")
        .map(|row| {
            let zone_id = t3_zone_for_route(&row.route)
                .map(|(zone_id, _)| zone_id.to_string())
                .unwrap_or_else(|| "zone-assignment-needed".to_string());
            let (
                access_class,
                obligation,
                decision,
                evidence,
                map_treatment,
                basis,
                next,
                effect,
                status,
            ) = t4_terminal_access_decision(row, &zone_id);
            let (
                hard_blocker_count,
                claim_blocker_count,
                constraint_debt_cost_m,
                lifecycle_debt_cost_m,
                constraint_penalty_score,
                top_constraint_classes,
                constraint_ledger_artifact,
            ) = constraint_budget_for_candidate(&row.route, "", constraint_budget_index);
            T4TerminalAccessColumnRow {
                route: row.route.clone(),
                zone_id,
                current_score: row.current_score,
                constraint_adjusted_score: row.current_score - constraint_penalty_score,
                hard_blocker_count,
                claim_blocker_count,
                constraint_debt_cost_m,
                lifecycle_debt_cost_m,
                constraint_penalty_score,
                top_constraint_classes,
                constraint_ledger_artifact,
                access_class: access_class.to_string(),
                terminal_obligation: obligation.to_string(),
                promise_horizon_hours: 1,
                column_decision: decision.to_string(),
                evidence_required: evidence.to_string(),
                map_treatment: map_treatment.to_string(),
                selection_basis: basis.to_string(),
                source_artifact: row.source_artifact.clone(),
                next_artifact: next.to_string(),
                optimizer_effect: effect.to_string(),
                validation_status: status.to_string(),
            }
        })
        .collect::<Vec<_>>();

    rows.sort_by(|a, b| {
        a.zone_id
            .cmp(&b.zone_id)
            .then_with(|| b.current_score.total_cmp(&a.current_score))
            .then_with(|| a.route.cmp(&b.route))
    });
    rows
}

fn t4_terminal_access_decision(
    row: &T3T4PressureIntakeRow,
    zone_id: &str,
) -> (
    String,
    String,
    String,
    String,
    String,
    String,
    String,
    String,
    String,
) {
    if zone_id == "zone-assignment-needed" {
        return (
            "unassigned-local-access".to_string(),
            "assign local route to a T3 zone or terminal district".to_string(),
            "zone-assignment-needed".to_string(),
            "zone boundary plus terminal/local freight role".to_string(),
            "hide-until-assigned".to_string(),
            "T4 pressure lacks a deterministic zone assignment".to_string(),
            "data/t3-t4-access-gaps.csv".to_string(),
            "blocks promotion and sends the route to access-gap triage".to_string(),
            "review".to_string(),
        );
    }

    if row.current_score >= T3_THRESHOLD - 5.0 {
        let (terminal_obligation, evidence_required) = t4_terminal_source_contract(zone_id);
        (
            "terminal-upgrade-candidate".to_string(),
            terminal_obligation.to_string(),
            "terminal-review".to_string(),
            evidence_required.to_string(),
            "show-as-local-inset-candidate".to_string(),
            "within five points of T3 threshold but still a T4/local access problem".to_string(),
            "data/t3-t4-access-gaps.csv".to_string(),
            "holds local pressure as a terminal access candidate instead of selecting T3"
                .to_string(),
            "review".to_string(),
        )
    } else {
        (
            "local-access-column".to_string(),
            "maintain one-hour local access to a freight terminal or district".to_string(),
            "selected-local-access".to_string(),
            "terminal/local obligation can be documented inside zone inset".to_string(),
            "render-in-local-inset".to_string(),
            "below T3 promotion pressure and suitable for T4 local access treatment".to_string(),
            "data/t3-zone-map-diagnostics.csv".to_string(),
            "keeps local service in T4 while exposing it to map diagnostics".to_string(),
            "pass".to_string(),
        )
    }
}

fn t4_terminal_source_contract(zone_id: &str) -> (&'static str, &'static str) {
    match zone_id {
        "t3-great-lakes" => (
            "prove one-hour access to a Great Lakes / Ohio Valley terminal district: Chicago Intermodal Complex, Columbus South, Indianapolis Avon, Detroit Livernois, Minneapolis Twin Cities, St. Louis Gateway, Philadelphia Frankford, or New York Fresh Pond",
            "cite a terminal district/contact source from data/intermodal_terminals.csv and attach the route to a selected T3/T2/T1 column",
        ),
        "t3-southeast" => (
            "prove one-hour access to a Southeast / Appalachia terminal district: Atlanta Hulsey, Charlotte Intermodal, Savannah Garden City, Miami Hialeah, or New Orleans Gentilly",
            "cite a terminal district/contact source from data/intermodal_terminals.csv and attach the route to a selected T3/T2/T1 column",
        ),
        "t3-texas-border" => (
            "prove one-hour access to a Texas Border / Gulf terminal district: Dallas Alliance, Houston Englewood, San Antonio Kirby, or New Orleans Gentilly",
            "cite a terminal district/contact source from data/intermodal_terminals.csv and attach the route to a selected T3/T2/T1 column",
        ),
        "t3-mountain-west" => (
            "prove one-hour access to a Mountain West / Interior terminal district: Denver Logistics Hub, Salt Lake City, Phoenix Sky Harbor area, Portland Albina, Seattle BNSF, Los Angeles/Long Beach, or Kansas City Gateway",
            "cite a terminal district/contact source from data/intermodal_terminals.csv and attach the route to a selected T3/T2/T1 column",
        ),
        "t3-mid-south" => (
            "prove one-hour access to a Mid-South / Delta / Ozarks terminal district: Memphis Intermodal, Kansas City Gateway, St. Louis Gateway, New Orleans Gentilly, or Louisville KentuckyOne",
            "cite a terminal district/contact source from data/intermodal_terminals.csv and attach the route to a selected T3/T2/T1 column",
        ),
        _ => (
            "prove one-hour terminal, port, yard, warehouse, or local freight access",
            "named terminal/local district plus contact to selected T3/T2/T1 column",
        ),
    }
}

