fn t4_terminal_contact_source_plan_gate_failures(
    rows: &[T4TerminalContactSourcePlanRow],
    contact_rows: &[T4TerminalContactEvidenceRow],
) -> Vec<String> {
    let mut failures = Vec::new();
    let expected_ids = contact_rows
        .iter()
        .filter(|row| row.zone_id == "t3-great-lakes" && row.decision == "source-needed")
        .map(|row| row.queue_id.as_str())
        .collect::<std::collections::BTreeSet<_>>();

    if rows.is_empty() {
        failures.push("no Great Lakes terminal contact source plan rows emitted".to_string());
        return failures;
    }
    if rows.len() != expected_ids.len() {
        failures.push(format!(
            "source plan has {} rows but expected {} Great Lakes source-needed rows",
            rows.len(),
            expected_ids.len()
        ));
    }

    let mut seen = std::collections::BTreeSet::<String>::new();
    for row in rows {
        if row.plan_id.trim().is_empty()
            || row.queue_id.trim().is_empty()
            || row.route.trim().is_empty()
            || row.zone_id.trim().is_empty()
            || row.terminal_district.trim().is_empty()
            || row.terminal_district_seed_source.trim().is_empty()
            || row.contact_proof_source_family.trim().is_empty()
            || row.required_proof_fields.trim().is_empty()
            || row.acquisition_status.trim().is_empty()
            || row.proof_blocker.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.validation_status.trim().is_empty()
        {
            failures.push(format!("{} has incomplete source plan fields", row.plan_id));
        }
        if !seen.insert(row.queue_id.clone()) {
            failures.push(format!(
                "{} appears more than once in source plan",
                row.queue_id
            ));
        }
        if row.zone_id != "t3-great-lakes" {
            failures.push(format!("{} is not a Great Lakes row", row.queue_id));
        }
        if !expected_ids.contains(row.queue_id.as_str()) {
            failures.push(format!(
                "{} is not a Great Lakes source-needed contact row",
                row.queue_id
            ));
        }
        if row.contact_proof_source_artifact == row.terminal_district_seed_source {
            failures.push(format!(
                "{} uses terminal district seed source as contact proof",
                row.queue_id
            ));
        }
        if !matches!(
            row.acquisition_status.as_str(),
            "source-needed" | "source-backed" | "blocked"
        ) {
            failures.push(format!(
                "{} has invalid acquisition status {}",
                row.queue_id, row.acquisition_status
            ));
        }
        if row.acquisition_status == "source-needed" {
            if row.contact_proof_source_artifact != "source-needed"
                || row.validation_status != "review"
            {
                failures.push(format!(
                    "{} source-needed row must keep source-needed proof artifact and review status",
                    row.queue_id
                ));
            }
            if !row.proof_blocker.contains("seed is not") {
                failures.push(format!(
                    "{} source-needed row lacks seed/proof blocker",
                    row.queue_id
                ));
            }
        }
        if row.acquisition_status == "source-backed"
            && row.contact_proof_source_artifact == "source-needed"
        {
            failures.push(format!(
                "{} source-backed row lacks contact proof artifact",
                row.queue_id
            ));
        }
        if !matches!(row.validation_status.as_str(), "pass" | "review" | "held") {
            failures.push(format!(
                "{} has invalid validation status {}",
                row.queue_id, row.validation_status
            ));
        }
    }

    for expected_id in expected_ids {
        if !seen.contains(expected_id) {
            failures.push(format!("{expected_id} is missing from source plan"));
        }
    }

    failures
}

fn t4_terminal_contact_source_catalog_gate_failures(
    rows: &[T4TerminalContactSourceCatalogRow],
    plan_rows: &[T4TerminalContactSourcePlanRow],
) -> Vec<String> {
    let mut failures = Vec::new();
    let expected = plan_rows.iter().fold(
        std::collections::BTreeMap::<String, usize>::new(),
        |mut counts, row| {
            *counts.entry(row.terminal_district.clone()).or_default() += 1;
            counts
        },
    );

    if rows.is_empty() {
        failures.push("no Great Lakes terminal district source catalog rows emitted".to_string());
        return failures;
    }
    if rows.len() != expected.len() {
        failures.push(format!(
            "source catalog has {} districts but expected {}",
            rows.len(),
            expected.len()
        ));
    }

    let mut seen = std::collections::BTreeSet::<String>::new();
    for row in rows {
        if row.catalog_id.trim().is_empty()
            || row.terminal_district.trim().is_empty()
            || row.source_family.trim().is_empty()
            || row.source_access_mode.trim().is_empty()
            || row.required_proof_fields.trim().is_empty()
            || row.acquisition_status.trim().is_empty()
            || row.proof_blocker.trim().is_empty()
            || row.cache_policy_artifact.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.validation_status.trim().is_empty()
        {
            failures.push(format!(
                "{} has incomplete source catalog fields",
                row.catalog_id
            ));
        }
        if !seen.insert(row.terminal_district.clone()) {
            failures.push(format!(
                "{} appears more than once in source catalog",
                row.terminal_district
            ));
        }
        match expected.get(&row.terminal_district) {
            Some(expected_count) if *expected_count == row.route_task_count => {}
            Some(expected_count) => failures.push(format!(
                "{} has {} route tasks but expected {}",
                row.terminal_district, row.route_task_count, expected_count
            )),
            None => failures.push(format!(
                "{} does not appear in the Great Lakes route source plan",
                row.terminal_district
            )),
        }
        if !row
            .required_proof_fields
            .contains("route-to-terminal contact statement")
        {
            failures.push(format!(
                "{} lacks route-to-terminal contact proof fields",
                row.terminal_district
            ));
        }
        if !matches!(
            row.acquisition_status.as_str(),
            "planned" | "source-needed" | "source-backed" | "blocked"
        ) {
            failures.push(format!(
                "{} has invalid acquisition status {}",
                row.terminal_district, row.acquisition_status
            ));
        }
        if row.acquisition_status == "source-needed"
            && (!row.source_access_mode.contains("source-needed")
                || row.validation_status != "review")
        {
            failures.push(format!(
                "{} source-needed catalog row must keep source-needed access mode and review status",
                row.terminal_district
            ));
        }
        if row.acquisition_status == "source-needed"
            && !row.proof_blocker.contains("no safe live fetcher")
        {
            failures.push(format!(
                "{} source-needed catalog row lacks fetch/cache blocker",
                row.terminal_district
            ));
        }
        if !matches!(row.validation_status.as_str(), "pass" | "review" | "held") {
            failures.push(format!(
                "{} has invalid validation status {}",
                row.terminal_district, row.validation_status
            ));
        }
    }

    for district in expected.keys() {
        if !seen.contains(district) {
            failures.push(format!("{district} is missing from source catalog"));
        }
    }

    failures
}

fn t4_terminal_contact_proof_docket_rows(
    plan_rows: &[T4TerminalContactSourcePlanRow],
    catalog_rows: &[T4TerminalContactSourceCatalogRow],
) -> Vec<T4TerminalContactProofDocketRow> {
    let catalog_by_district = catalog_rows
        .iter()
        .map(|row| (row.terminal_district.as_str(), row))
        .collect::<std::collections::BTreeMap<_, _>>();

    let mut rows = plan_rows
        .iter()
        .map(|row| {
            let catalog = catalog_by_district.get(row.terminal_district.as_str());
            T4TerminalContactProofDocketRow {
                task_id: format!("T4PROOF-{}", stable_id_fragment(&row.queue_id)),
                queue_id: row.queue_id.clone(),
                route: row.route.clone(),
                zone_id: row.zone_id.clone(),
                terminal_district: row.terminal_district.clone(),
                source_family: catalog
                    .map(|catalog| catalog.source_family.clone())
                    .unwrap_or_else(|| row.contact_proof_source_family.clone()),
                required_proof_field: "route-to-terminal contact statement".to_string(),
                selected_higher_tier_attachment_requirement:
                    "must name selected higher-tier attachment or remain source-needed".to_string(),
                contact_proof_source_artifact: row.contact_proof_source_artifact.clone(),
                proof_status: "source-needed".to_string(),
                proof_blocker: row.proof_blocker.clone(),
                scenario_effect:
                    "no scenario-readiness until contact proof source and attachment are accepted"
                        .to_string(),
                next_artifact:
                    "waves/2026-05-13-great-lakes-terminal-contact-sources/plans/pulse-04.md"
                        .to_string(),
                validation_status: "review".to_string(),
            }
        })
        .collect::<Vec<_>>();

    rows.sort_by(|a, b| {
        a.terminal_district
            .cmp(&b.terminal_district)
            .then_with(|| a.route.cmp(&b.route))
            .then_with(|| a.queue_id.cmp(&b.queue_id))
    });
    rows
}

fn write_t4_terminal_contact_proof_docket(
    path: &Path,
    rows: &[T4TerminalContactProofDocketRow],
) -> Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("creating {}", parent.display()))?;
    }
    let mut writer = csv::Writer::from_path(path)?;
    for row in rows {
        writer.serialize(row)?;
    }
    writer.flush()?;
    Ok(())
}

fn print_t4_terminal_contact_proof_docket_summary(
    output: &Path,
    rows: &[T4TerminalContactProofDocketRow],
) {
    let mut by_status = std::collections::BTreeMap::<&str, usize>::new();
    for row in rows {
        *by_status.entry(row.proof_status.as_str()).or_default() += 1;
    }
    println!(
        "  wrote {} T4 terminal contact proof docket rows to {}",
        rows.len(),
        output.display()
    );
    for (status, count) in by_status {
        println!("  {status}: {count}");
    }
}

fn t4_terminal_contact_proof_docket_gate_failures(
    rows: &[T4TerminalContactProofDocketRow],
    plan_rows: &[T4TerminalContactSourcePlanRow],
    catalog_rows: &[T4TerminalContactSourceCatalogRow],
) -> Vec<String> {
    let mut failures = Vec::new();
    let expected_ids = plan_rows
        .iter()
        .map(|row| row.queue_id.as_str())
        .collect::<std::collections::BTreeSet<_>>();
    let catalog_districts = catalog_rows
        .iter()
        .map(|row| row.terminal_district.as_str())
        .collect::<std::collections::BTreeSet<_>>();

    if rows.is_empty() {
        failures.push("no Great Lakes terminal contact proof docket rows emitted".to_string());
        return failures;
    }
    if rows.len() != expected_ids.len() {
        failures.push(format!(
            "proof docket has {} rows but expected {} source-plan rows",
            rows.len(),
            expected_ids.len()
        ));
    }

    let mut seen = std::collections::BTreeSet::<String>::new();
    for row in rows {
        if row.task_id.trim().is_empty()
            || row.queue_id.trim().is_empty()
            || row.route.trim().is_empty()
            || row.zone_id.trim().is_empty()
            || row.terminal_district.trim().is_empty()
            || row.source_family.trim().is_empty()
            || row.required_proof_field.trim().is_empty()
            || row
                .selected_higher_tier_attachment_requirement
                .trim()
                .is_empty()
            || row.proof_status.trim().is_empty()
            || row.proof_blocker.trim().is_empty()
            || row.scenario_effect.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.validation_status.trim().is_empty()
        {
            failures.push(format!(
                "{} has incomplete proof docket fields",
                row.task_id
            ));
        }
        if !seen.insert(row.queue_id.clone()) {
            failures.push(format!(
                "{} appears more than once in proof docket",
                row.queue_id
            ));
        }
        if row.zone_id != "t3-great-lakes" {
            failures.push(format!("{} is not a Great Lakes proof task", row.queue_id));
        }
        if !expected_ids.contains(row.queue_id.as_str()) {
            failures.push(format!(
                "{} does not appear in the Great Lakes source plan",
                row.queue_id
            ));
        }
        if !catalog_districts.contains(row.terminal_district.as_str()) {
            failures.push(format!(
                "{} lacks district source-family catalog row",
                row.queue_id
            ));
        }
        if row.required_proof_field != "route-to-terminal contact statement" {
            failures.push(format!(
                "{} has invalid proof field {}",
                row.queue_id, row.required_proof_field
            ));
        }
        if !row
            .selected_higher_tier_attachment_requirement
            .contains("selected higher-tier attachment")
        {
            failures.push(format!(
                "{} lacks higher-tier attachment requirement",
                row.queue_id
            ));
        }
        if !matches!(
            row.proof_status.as_str(),
            "source-needed" | "source-backed" | "blocked"
        ) {
            failures.push(format!(
                "{} has invalid proof status {}",
                row.queue_id, row.proof_status
            ));
        }
        if row.proof_status == "source-needed" {
            if row.contact_proof_source_artifact != "source-needed"
                || row.validation_status != "review"
            {
                failures.push(format!(
                    "{} source-needed proof task must keep source-needed proof artifact and review status",
                    row.queue_id
                ));
            }
            if !row.scenario_effect.contains("no scenario-readiness") {
                failures.push(format!(
                    "{} source-needed proof task must block scenario-readiness",
                    row.queue_id
                ));
            }
        }
        if row.proof_status == "source-backed"
            && row.contact_proof_source_artifact == "source-needed"
        {
            failures.push(format!(
                "{} source-backed proof task lacks proof artifact",
                row.queue_id
            ));
        }
        if !matches!(row.validation_status.as_str(), "pass" | "review" | "held") {
            failures.push(format!(
                "{} has invalid validation status {}",
                row.queue_id, row.validation_status
            ));
        }
    }

    for expected_id in expected_ids {
        if !seen.contains(expected_id) {
            failures.push(format!("{expected_id} is missing from proof docket"));
        }
    }

    failures
}

