fn t3_zone_map_diagnostic_gate_failures(
    rows: &[T3ZoneMapDiagnosticRow],
    atlas_rows: &[MapAtlasRow],
) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T3 zone map diagnostics emitted".to_string());
        return failures;
    }

    let t3_maps = t3_zone_map_ids(atlas_rows);
    let row_maps = rows
        .iter()
        .map(|row| row.map_id.clone())
        .collect::<std::collections::BTreeSet<_>>();
    for map_id in &t3_maps {
        if !row_maps.contains(map_id) {
            failures.push(format!("{map_id} has no map diagnostic row"));
        }
    }

    let mut seen = std::collections::BTreeSet::<String>::new();
    for row in rows {
        if row.zone_id.trim().is_empty()
            || row.zone_name.trim().is_empty()
            || row.map_id.trim().is_empty()
            || row.map_path.trim().is_empty()
            || row.map_readiness.trim().is_empty()
            || row.diagnostic_action.trim().is_empty()
            || row.next_artifact.trim().is_empty()
        {
            failures.push(format!(
                "{} has incomplete map diagnostic fields",
                row.zone_id
            ));
        }
        if !seen.insert(row.zone_id.clone()) {
            failures.push(format!("{} has duplicate map diagnostic row", row.zone_id));
        }
        if row.zone_id != row.map_id {
            failures.push(format!(
                "{} is detached from map id {}",
                row.zone_id, row.map_id
            ));
        }
        if !t3_maps.contains(&row.map_id) {
            failures.push(format!("{} references unknown T3 map", row.zone_id));
        }
        if row.selected_route_count == 0 {
            failures.push(format!("{} has no selected T3 feeder routes", row.zone_id));
        }
        if row.selected_route_count > 0 && row.selected_routes.trim().is_empty() {
            failures.push(format!(
                "{} has selected count but no route list",
                row.zone_id
            ));
        }
        if !matches!(row.validation_status.as_str(), "pass" | "review") {
            failures.push(format!(
                "{} has invalid validation status {}",
                row.zone_id, row.validation_status
            ));
        }
    }

    failures
}

fn load_t3_zone_map_diagnostics(path: &Path) -> Result<Vec<T3ZoneMapDiagnosticRow>> {
    if !path.exists() {
        return Ok(Vec::new());
    }
    let mut reader = csv::Reader::from_path(path)?;
    let mut rows = Vec::new();
    for row in reader.deserialize() {
        rows.push(row?);
    }
    Ok(rows)
}

fn t3_zone_render_board_rows(
    diagnostic_rows: &[T3ZoneMapDiagnosticRow],
    route_rows: &[T3ZoneRouteColumnRow],
    gap_rows: &[T3T4AccessGapRow],
    atlas_rows: &[MapAtlasRow],
) -> Vec<T3ZoneRenderBoardRow> {
    let atlas_by_id = atlas_rows
        .iter()
        .filter(|row| row.map_type == "t3-zone")
        .map(|row| (row.map_id.as_str(), row))
        .collect::<std::collections::BTreeMap<_, _>>();
    let mut rows = Vec::new();

    for diagnostic in diagnostic_rows {
        let map_path = atlas_by_id
            .get(diagnostic.map_id.as_str())
            .map(|row| row.path.as_str())
            .unwrap_or(diagnostic.map_path.as_str());
        rows.push(T3ZoneRenderBoardRow {
            zone_id: diagnostic.zone_id.clone(),
            zone_name: diagnostic.zone_name.clone(),
            map_id: diagnostic.map_id.clone(),
            map_path: map_path.to_string(),
            board_layer: "zone-summary".to_string(),
            route: String::new(),
            national_segment_id: t3_national_segment_id(&diagnostic.zone_id, ""),
            stitch_group_id: t3_stitch_group_id(&diagnostic.zone_id, ""),
            segment_bundle_id: t3_segment_bundle_id(&diagnostic.zone_id, ""),
            segment_aliases: t3_segment_aliases(&diagnostic.zone_id, "", "zone-summary"),
            route_status: diagnostic.map_readiness.clone(),
            map_treatment: "render-zone-summary".to_string(),
            selected_route_count: diagnostic.selected_route_count,
            access_gap_count: diagnostic.access_gap_count,
            source_artifact: "data/t3-zone-map-diagnostics.csv".to_string(),
            render_action: diagnostic.diagnostic_action.clone(),
            next_artifact: "maps/t3-zone".to_string(),
            validation_status: diagnostic.validation_status.clone(),
        });

        let mut zone_routes = route_rows
            .iter()
            .filter(|row| row.zone_id == diagnostic.zone_id)
            .collect::<Vec<_>>();
        zone_routes.sort_by(|a, b| {
            route_layer_rank(&a.column_decision)
                .cmp(&route_layer_rank(&b.column_decision))
                .then_with(|| b.current_score.total_cmp(&a.current_score))
                .then_with(|| a.route.cmp(&b.route))
        });

        for route in zone_routes {
            let board_layer = match route.column_decision.as_str() {
                "selected" => "selected-route",
                _ => "review-connector",
            };
            rows.push(T3ZoneRenderBoardRow {
                zone_id: diagnostic.zone_id.clone(),
                zone_name: diagnostic.zone_name.clone(),
                map_id: diagnostic.map_id.clone(),
                map_path: map_path.to_string(),
                board_layer: board_layer.to_string(),
                route: route.route.clone(),
                national_segment_id: t3_national_segment_id(&diagnostic.zone_id, &route.route),
                stitch_group_id: t3_stitch_group_id(&diagnostic.zone_id, &route.route),
                segment_bundle_id: t3_segment_bundle_id(&diagnostic.zone_id, &route.route),
                segment_aliases: t3_segment_aliases(&diagnostic.zone_id, &route.route, board_layer),
                route_status: route.column_decision.clone(),
                map_treatment: route.map_treatment.clone(),
                selected_route_count: diagnostic.selected_route_count,
                access_gap_count: diagnostic.access_gap_count,
                source_artifact: "data/t3-zone-route-columns.csv".to_string(),
                render_action: route_render_action(route),
                next_artifact: "maps/t3-zone".to_string(),
                validation_status: route.validation_status.clone(),
            });
        }

        let mut zone_gaps = gap_rows
            .iter()
            .filter(|row| row.zone_id == diagnostic.zone_id)
            .collect::<Vec<_>>();
        zone_gaps.sort_by(|a, b| {
            a.gap_class
                .cmp(&b.gap_class)
                .then_with(|| b.current_score.total_cmp(&a.current_score))
                .then_with(|| a.route.cmp(&b.route))
        });
        for gap in zone_gaps {
            rows.push(T3ZoneRenderBoardRow {
                zone_id: diagnostic.zone_id.clone(),
                zone_name: diagnostic.zone_name.clone(),
                map_id: diagnostic.map_id.clone(),
                map_path: map_path.to_string(),
                board_layer: "held-gap".to_string(),
                route: gap.route.clone(),
                national_segment_id: t3_national_segment_id(&diagnostic.zone_id, &gap.route),
                stitch_group_id: t3_stitch_group_id(&diagnostic.zone_id, &gap.route),
                segment_bundle_id: t3_segment_bundle_id(&diagnostic.zone_id, &gap.route),
                segment_aliases: t3_segment_aliases(&diagnostic.zone_id, &gap.route, "held-gap"),
                route_status: gap.gap_class.clone(),
                map_treatment: "render-gap-callout".to_string(),
                selected_route_count: diagnostic.selected_route_count,
                access_gap_count: diagnostic.access_gap_count,
                source_artifact: gap.source_surface.clone(),
                render_action: gap.repair_action.clone(),
                next_artifact: gap.next_artifact.clone(),
                validation_status: gap.validation_status.clone(),
            });
        }
    }

    let unassigned_gaps = gap_rows
        .iter()
        .filter(|row| row.zone_id == "zone-assignment-needed")
        .collect::<Vec<_>>();
    if !unassigned_gaps.is_empty() {
        rows.push(T3ZoneRenderBoardRow {
            zone_id: "zone-assignment-needed".to_string(),
            zone_name: "Unassigned Terminal / Local Access".to_string(),
            map_id: "zone-assignment-needed".to_string(),
            map_path: "data/t3-t4-access-gaps.csv".to_string(),
            board_layer: "unassigned-gap-backlog".to_string(),
            route: String::new(),
            national_segment_id: t3_national_segment_id("zone-assignment-needed", ""),
            stitch_group_id: t3_stitch_group_id("zone-assignment-needed", ""),
            segment_bundle_id: t3_segment_bundle_id("zone-assignment-needed", ""),
            segment_aliases: t3_segment_aliases(
                "zone-assignment-needed",
                "",
                "unassigned-gap-backlog",
            ),
            route_status: "zone-assignment-needed".to_string(),
            map_treatment: "hide-until-assigned".to_string(),
            selected_route_count: 0,
            access_gap_count: unassigned_gaps.len(),
            source_artifact: "data/t3-t4-access-gaps.csv".to_string(),
            render_action: "assign-zone-or-terminal-district-before-render".to_string(),
            next_artifact: "data/t3-t4-access-gaps.csv".to_string(),
            validation_status: "review".to_string(),
        });
    }

    rows.sort_by(|a, b| {
        a.zone_id
            .cmp(&b.zone_id)
            .then_with(|| board_layer_rank(&a.board_layer).cmp(&board_layer_rank(&b.board_layer)))
            .then_with(|| a.route.cmp(&b.route))
            .then_with(|| a.route_status.cmp(&b.route_status))
    });
    rows
}

fn route_layer_rank(column_decision: &str) -> u8 {
    match column_decision {
        "selected" => 0,
        "upward-review" => 1,
        "review" => 2,
        _ => 3,
    }
}

fn board_layer_rank(board_layer: &str) -> u8 {
    match board_layer {
        "zone-summary" => 0,
        "selected-route" => 1,
        "review-connector" => 2,
        "held-gap" => 3,
        "unassigned-gap-backlog" => 4,
        _ => 5,
    }
}

fn t3_national_segment_id(zone_id: &str, route: &str) -> String {
    format!(
        "US.HWYSEG.{:016X}",
        stable_segment_hash(&format!(
            "{}|{}",
            zone_id.trim(),
            normalise_designation(route)
        ))
    )
}

fn t3_stitch_group_id(zone_id: &str, route: &str) -> String {
    format!(
        "US.HWYSTITCH.{:016X}",
        stable_segment_hash(&format!(
            "{}|{}",
            zone_id.trim(),
            normalise_designation(route)
        ))
    )
}

fn t3_segment_bundle_id(zone_id: &str, route: &str) -> String {
    format!(
        "US.HWYBUNDLE.{:016X}",
        stable_segment_hash(&format!(
            "{}|{}",
            zone_id.trim(),
            normalise_designation(route)
        ))
    )
}

fn t3_segment_aliases(zone_id: &str, route: &str, layer: &str) -> String {
    let mut aliases = vec![
        "current-tier:T3".to_string(),
        format!("current-zone:{}", zone_id.trim()),
        format!("layer:{}", layer.trim()),
    ];
    let route = normalise_designation(route);
    if !route.is_empty() {
        aliases.push(format!("route:{route}"));
        aliases.push(format!("route-label:{route}"));
        aliases.push(format!("zone-route:{}:{route}", zone_id.trim()));
    }
    aliases.join(";")
}

fn stable_segment_hash(value: &str) -> u64 {
    let mut hash = 0xcbf29ce484222325u64;
    for byte in value.as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}

fn route_render_action(row: &T3ZoneRouteColumnRow) -> String {
    match row.column_decision.as_str() {
        "selected" => "render selected T3 route column with stop placement constraints".to_string(),
        "upward-review" => "show as review connector without promotion".to_string(),
        "review" => "show as held feeder candidate only through gap callout".to_string(),
        _ => "hold route outside rendered zone board".to_string(),
    }
}

fn write_t3_zone_render_board(path: &Path, rows: &[T3ZoneRenderBoardRow]) -> Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("creating {}", parent.display()))?;
    }
    let mut writer = csv::Writer::from_path(path)?;
    for row in rows {
        writer.serialize(row)?;
    }
    writer.flush()?;
    Ok(())
}

fn print_t3_zone_render_board_summary(output: &Path, rows: &[T3ZoneRenderBoardRow]) {
    let mut by_layer = std::collections::BTreeMap::<&str, usize>::new();
    for row in rows {
        *by_layer.entry(row.board_layer.as_str()).or_default() += 1;
    }
    println!(
        "  wrote {} T3 zone render board rows to {}",
        rows.len(),
        output.display()
    );
    for (layer, count) in by_layer {
        println!("  {layer}: {count}");
    }
}

fn t3_zone_render_board_gate_failures(
    rows: &[T3ZoneRenderBoardRow],
    atlas_rows: &[MapAtlasRow],
) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T3 zone render board rows emitted".to_string());
        return failures;
    }

    let t3_maps = t3_zone_map_ids(atlas_rows);
    let summary_maps = rows
        .iter()
        .filter(|row| row.board_layer == "zone-summary")
        .map(|row| row.map_id.clone())
        .collect::<std::collections::BTreeSet<_>>();
    for map_id in &t3_maps {
        if !summary_maps.contains(map_id) {
            failures.push(format!("{map_id} has no zone-summary render row"));
        }
    }

    for row in rows {
        if row.zone_id.trim().is_empty()
            || row.zone_name.trim().is_empty()
            || row.map_id.trim().is_empty()
            || row.map_path.trim().is_empty()
            || row.board_layer.trim().is_empty()
            || row.national_segment_id.trim().is_empty()
            || row.stitch_group_id.trim().is_empty()
            || row.segment_bundle_id.trim().is_empty()
            || row.segment_aliases.trim().is_empty()
            || row.route_status.trim().is_empty()
            || row.map_treatment.trim().is_empty()
            || row.source_artifact.trim().is_empty()
            || row.render_action.trim().is_empty()
            || row.next_artifact.trim().is_empty()
        {
            failures.push(format!(
                "{} {} {} has incomplete render board fields",
                row.zone_id, row.board_layer, row.route
            ));
        }
        if !matches!(row.validation_status.as_str(), "pass" | "review") {
            failures.push(format!(
                "{} {} has invalid validation status {}",
                row.zone_id, row.board_layer, row.validation_status
            ));
        }
        if row.zone_id != "zone-assignment-needed" {
            if row.zone_id != row.map_id {
                failures.push(format!(
                    "{} render row detached from map id {}",
                    row.zone_id, row.map_id
                ));
            }
            if !t3_maps.contains(&row.map_id) {
                failures.push(format!("{} references unknown T3 map", row.zone_id));
            }
        }
        if row.board_layer == "zone-summary" && row.selected_route_count == 0 {
            failures.push(format!(
                "{} has no selected route render count",
                row.zone_id
            ));
        }
        if matches!(
            row.board_layer.as_str(),
            "selected-route" | "review-connector" | "held-gap"
        ) && row.route.trim().is_empty()
        {
            failures.push(format!(
                "{} {} is missing route",
                row.zone_id, row.board_layer
            ));
        }
        if !row.national_segment_id.starts_with("US.HWYSEG.") {
            failures.push(format!(
                "{} {} has non-hierarchical segment id {}",
                row.zone_id, row.route, row.national_segment_id
            ));
        }
        if !row.stitch_group_id.starts_with("US.HWYSTITCH.") {
            failures.push(format!(
                "{} {} has non-hierarchical stitch group {} for segment id {}",
                row.zone_id, row.route, row.stitch_group_id, row.national_segment_id
            ));
        }
        if !row.segment_bundle_id.starts_with("US.HWYBUNDLE.") {
            failures.push(format!(
                "{} {} has non-hierarchical bundle id {}",
                row.zone_id, row.route, row.segment_bundle_id
            ));
        }
        if row.board_layer == "selected-route"
            && (row.route_status != "selected" || row.map_treatment != "render-as-zone-column")
        {
            failures.push(format!(
                "{} {} selected route is not renderable",
                row.zone_id, row.route
            ));
        }
        if row.board_layer == "unassigned-gap-backlog" && row.map_treatment != "hide-until-assigned"
        {
            failures.push("unassigned backlog must stay hidden until assigned".to_string());
        }
    }

    failures
}

fn load_t3_zone_render_board(path: &Path) -> Result<Vec<T3ZoneRenderBoardRow>> {
    if !path.exists() {
        return Ok(Vec::new());
    }
    let mut reader = csv::Reader::from_path(path)?;
    let mut rows = Vec::new();
    for row in reader.deserialize() {
        rows.push(row?);
    }
    Ok(rows)
}

fn t3_zone_stop_placement_rows(
    board_rows: &[T3ZoneRenderBoardRow],
    stop_rows: &[StopCandidateRow],
) -> Vec<T3ZoneStopPlacementRow> {
    let mut rows = board_rows
        .iter()
        .filter(|row| row.board_layer == "selected-route")
        .map(|board| {
            let stop_plan = t3_zone_stop_plan_for_route(stop_rows, &board.route, &board.zone_id);
            let transfer_grade_stop_count = stop_plan
                .iter()
                .filter(|stop| t3_transfer_grade_stop(stop))
                .count();
            let stop_chain = stop_plan
                .iter()
                .map(|stop| stop.stop_id.as_str())
                .collect::<Vec<_>>()
                .join(";");
            let stop_classes = stop_plan
                .iter()
                .map(|stop| stop.requested_class.trim())
                .filter(|class| !class.is_empty())
                .collect::<std::collections::BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>()
                .join(";");
            let state_scope = t3_stop_state_scope(&stop_plan);
            let (placement_status, placement_action, next_artifact, validation_status) =
                t3_zone_stop_placement_decision(stop_plan.len(), transfer_grade_stop_count);

            T3ZoneStopPlacementRow {
                zone_id: board.zone_id.clone(),
                zone_name: board.zone_name.clone(),
                route: board.route.clone(),
                national_segment_id: board.national_segment_id.clone(),
                stitch_group_id: board.stitch_group_id.clone(),
                segment_bundle_id: board.segment_bundle_id.clone(),
                segment_aliases: board.segment_aliases.clone(),
                state_scope,
                stop_count: stop_plan.len(),
                transfer_grade_stop_count,
                stop_chain,
                stop_classes,
                placement_status: placement_status.to_string(),
                placement_action: placement_action.to_string(),
                source_artifact: "data/t3-zone-render-board.csv; data/tier-stop-candidates.csv"
                    .to_string(),
                next_artifact: next_artifact.to_string(),
                validation_status: validation_status.to_string(),
            }
        })
        .collect::<Vec<_>>();

    rows.sort_by(|a, b| {
        a.zone_id
            .cmp(&b.zone_id)
            .then_with(|| a.placement_status.cmp(&b.placement_status))
            .then_with(|| a.route.cmp(&b.route))
    });
    rows
}

fn t3_transfer_grade_stop(stop: &StopCandidateRow) -> bool {
    matches!(
        stop.requested_class.trim().to_ascii_uppercase().as_str(),
        "S1" | "S2" | "S3"
    )
}

fn t3_stop_state_scope(stops: &[&StopCandidateRow]) -> String {
    stops
        .iter()
        .flat_map(|stop| stop.state.split(['/', ';', ',']))
        .map(|state| state.trim().to_ascii_uppercase())
        .filter(|state| !state.is_empty())
        .collect::<std::collections::BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>()
        .join(";")
}

fn t3_zone_stop_plan_for_route<'a>(
    rows: &'a [StopCandidateRow],
    route: &str,
    zone_id: &str,
) -> Vec<&'a StopCandidateRow> {
    let mut stops = stop_plan_for_route(rows, route)
        .into_iter()
        .filter(|stop| t3_stop_in_zone(stop, zone_id))
        .collect::<Vec<_>>();
    sort_stops_for_route(&mut stops);
    stops
}

fn t3_stop_in_zone(stop: &StopCandidateRow, zone_id: &str) -> bool {
    let Some((min_lat, max_lat, min_lon, max_lon)) = t3_zone_bounds(zone_id) else {
        return true;
    };
    let Some(lat) = parse_coord(&stop.lat) else {
        return false;
    };
    let Some(lon) = parse_coord(&stop.lon) else {
        return false;
    };
    (min_lat..=max_lat).contains(&lat) && (min_lon..=max_lon).contains(&lon)
}

fn t3_zone_bounds(zone_id: &str) -> Option<(f64, f64, f64, f64)> {
    match zone_id {
        "t3-great-lakes" => Some((37.0, 46.5, -92.0, -74.0)),
        "t3-southeast" => Some((25.0, 39.5, -91.5, -75.0)),
        "t3-texas-border" => Some((25.0, 34.5, -107.5, -93.0)),
        "t3-mountain-west" => Some((31.0, 49.5, -125.0, -102.0)),
        "t3-mid-south" => Some((29.0, 40.5, -96.5, -75.0)),
        _ => None,
    }
}

fn t3_zone_stop_placement_decision(
    stop_count: usize,
    transfer_grade_stop_count: usize,
) -> (&'static str, &'static str, &'static str, &'static str) {
    if stop_count >= 2 && transfer_grade_stop_count >= 1 {
        (
            "ready-for-stop-layout",
            "place route on zone schematic using ordered stop chain",
            "maps/t3-zone",
            "pass",
        )
    } else if stop_count == 1 {
        (
            "needs-terminal-stop",
            "author one additional transfer or regional terminal stop before geometry",
            "data/tier-stop-candidates.csv",
            "review",
        )
    } else {
        (
            "needs-stop-chain",
            "author at least two visible T3 zone stops before geometry",
            "data/tier-stop-candidates.csv",
            "review",
        )
    }
}

