fn load_t1_sla_candidate_universe(path: &Path) -> Result<Vec<T1SlaCandidateUniverseRow>> {
    let mut reader = csv::Reader::from_path(path)?;
    let mut rows = Vec::new();
    for row in reader.deserialize() {
        rows.push(row?);
    }
    Ok(rows)
}

fn t1_sla_candidate_pair_rows(
    candidate_rows: &[T1SlaCandidateUniverseRow],
    selected_rows: &[T1SlaPairRow],
    selected_budget: usize,
) -> Vec<T1SlaCandidatePairRow> {
    let selected_pair_ids = selected_rows
        .iter()
        .map(|row| row.pair_id.trim().to_string())
        .collect::<std::collections::BTreeSet<_>>();
    let mut rows = candidate_rows
        .iter()
        .map(|row| {
            let total_score = t1_sla_candidate_pair_score(row);
            let portfolio_selected = selected_pair_ids.contains(row.pair_id.trim());
            T1SlaCandidatePairRow {
                rank: 0,
                pair_id: row.pair_id.clone(),
                origin_id: row.origin_id.clone(),
                dest_id: row.dest_id.clone(),
                target_hours: row.target_hours,
                market_class: row.market_class.clone(),
                total_score,
                market_score: row.market_score,
                conversion_score: row.conversion_score,
                coverage_score: row.coverage_score,
                reuse_score: row.reuse_score,
                resilience_score: row.resilience_score,
                evidence_score: row.evidence_score,
                budget_penalty: row.budget_penalty,
                portfolio_selected,
                selected_budget,
                cutline_status: String::new(),
                cutline_reason: String::new(),
                covered_by_selected_pair: row.covered_by_selected_pair.clone(),
                required_routes: row.required_routes.clone(),
                required_stops: row.required_stops.clone(),
                evidence_basis: row.evidence_basis.clone(),
                validation_status: String::new(),
            }
        })
        .collect::<Vec<_>>();
    rows.sort_by(|a, b| {
        b.total_score
            .total_cmp(&a.total_score)
            .then_with(|| b.portfolio_selected.cmp(&a.portfolio_selected))
            .then_with(|| a.pair_id.cmp(&b.pair_id))
    });

    for (idx, row) in rows.iter_mut().enumerate() {
        row.rank = idx + 1;
        if row.portfolio_selected {
            row.cutline_status = "selected-portfolio".to_string();
            row.cutline_reason = "inside-selected-t1-promise-budget".to_string();
            row.validation_status = "pass".to_string();
        } else if row.rank <= selected_budget {
            row.cutline_status = "ranked-above-cutline-but-unselected".to_string();
            row.cutline_reason = "candidate-score-conflicts-with-selected-portfolio".to_string();
            row.validation_status = "review".to_string();
        } else {
            row.cutline_status = "dropped-at-cutline".to_string();
            row.cutline_reason = candidate_rows
                .iter()
                .find(|candidate| candidate.pair_id == row.pair_id)
                .map(|candidate| candidate.drop_reason_hint.trim())
                .filter(|hint| !hint.is_empty())
                .unwrap_or("below-selected-budget-cutline")
                .to_string();
            row.validation_status = "pass".to_string();
        }
    }
    rows
}

fn t1_sla_candidate_pair_score(row: &T1SlaCandidateUniverseRow) -> f64 {
    row.market_score
        + row.conversion_score
        + row.coverage_score
        + row.reuse_score
        + row.resilience_score
        + row.evidence_score
        - row.budget_penalty
}

fn write_t1_sla_candidate_pairs(path: &Path, rows: &[T1SlaCandidatePairRow]) -> Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("creating {}", parent.display()))?;
    }
    let mut writer = csv::Writer::from_path(path)?;
    for row in rows {
        writer.serialize(row)?;
    }
    writer.flush()?;
    Ok(())
}

fn print_t1_sla_candidate_pair_summary(
    output: &Path,
    rows: &[T1SlaCandidatePairRow],
    selected_budget: usize,
) {
    let selected = rows.iter().filter(|row| row.portfolio_selected).count();
    let dropped = rows.iter().filter(|row| !row.portfolio_selected).count();
    let cutline = rows
        .iter()
        .find(|row| row.rank == selected_budget + 1)
        .map(|row| row.pair_id.as_str())
        .unwrap_or("n/a");
    println!(
        "  wrote {} ranked SLA candidate pairs to {}",
        rows.len(),
        output.display()
    );
    println!("  selected portfolio rows: {selected}/{selected_budget}");
    println!("  dropped candidate rows: {dropped}");
    println!("  first dropped by rank: {cutline}");
}

fn t1_sla_candidate_pair_gate_failures(
    rows: &[T1SlaCandidatePairRow],
    selected_rows: &[T1SlaPairRow],
    selected_budget: usize,
) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T1 SLA candidate pairs emitted".to_string());
        return failures;
    }
    let selected_count = rows.iter().filter(|row| row.portfolio_selected).count();
    if selected_count != selected_budget {
        failures.push(format!(
            "selected portfolio has {selected_count} rows, expected {selected_budget}"
        ));
    }
    let row_pair_ids = rows
        .iter()
        .map(|row| row.pair_id.as_str())
        .collect::<std::collections::BTreeSet<_>>();
    for selected in selected_rows {
        if !row_pair_ids.contains(selected.pair_id.as_str()) {
            failures.push(format!(
                "{} selected pair missing from candidate universe",
                selected.pair_id
            ));
        }
    }
    if rows
        .iter()
        .any(|row| row.cutline_status == "ranked-above-cutline-but-unselected")
    {
        failures.push("unselected candidate ranked above selected budget cutline".to_string());
    }
    for row in rows {
        if row.pair_id.trim().is_empty()
            || row.origin_id.trim().is_empty()
            || row.dest_id.trim().is_empty()
            || row.market_class.trim().is_empty()
            || row.required_routes.trim().is_empty()
            || row.required_stops.trim().is_empty()
            || row.evidence_basis.trim().is_empty()
            || row.cutline_status.trim().is_empty()
            || row.cutline_reason.trim().is_empty()
            || row.validation_status.trim().is_empty()
        {
            failures.push(format!("{} has incomplete candidate-pair row", row.pair_id));
        }
        if !matches!(row.target_hours.round() as u16, 36 | 48) {
            failures.push(format!(
                "{} has unsupported T1 target_hours {}",
                row.pair_id, row.target_hours
            ));
        }
        if !row.portfolio_selected
            && row.cutline_status == "dropped-at-cutline"
            && row.covered_by_selected_pair.trim().is_empty()
            && !row.cutline_reason.contains("source")
            && !row.cutline_reason.contains("budget")
            && !row.cutline_reason.contains("lower-tier")
        {
            failures.push(format!(
                "{} dropped without coverage, source, budget, or lower-tier reason",
                row.pair_id
            ));
        }
    }
    failures
}

fn t1_line_selector_rows(
    tier_table: &Path,
    stop_candidates: &Path,
    sla_pairs: &Path,
    score_exceptions: &Path,
    constraint_budget: &Path,
    route_budget: usize,
    city_budget: usize,
    stop_budget: usize,
) -> Result<Vec<T1LineSelectorRow>> {
    let mut tier_rows = csv::Reader::from_path(tier_table)
        .with_context(|| format!("reading {}", tier_table.display()))?
        .deserialize::<TierTableInputRow>()
        .collect::<Result<Vec<_>, _>>()
        .with_context(|| format!("parsing {}", tier_table.display()))?;
    let sla_rows = csv::Reader::from_path(sla_pairs)
        .with_context(|| format!("reading {}", sla_pairs.display()))?
        .deserialize::<T1SlaPairRow>()
        .collect::<Result<Vec<_>, _>>()
        .with_context(|| format!("parsing {}", sla_pairs.display()))?;
    let score_exception_rows = load_t1_score_exceptions(score_exceptions)
        .with_context(|| format!("loading {}", score_exceptions.display()))?;
    let constraint_budget_rows = load_optimizer_constraint_budget(constraint_budget)
        .with_context(|| format!("loading {}", constraint_budget.display()))?;
    let constraint_budget_index = optimizer_constraint_budget_index(&constraint_budget_rows);
    let demoted_score_routes = score_exception_rows
        .iter()
        .filter(|row| matches!(row.decision.trim(), "demote" | "replace"))
        .map(|row| normalise_designation(&row.route))
        .collect::<std::collections::BTreeSet<_>>();
    let score_exception_decisions = score_exception_rows
        .iter()
        .map(|row| {
            (
                normalise_designation(&row.route),
                row.decision.trim().to_string(),
            )
        })
        .collect::<std::collections::BTreeMap<_, _>>();
    let mut required_route_pairs = std::collections::BTreeMap::<String, Vec<String>>::new();
    let mut required_route_priority = std::collections::BTreeMap::<String, u8>::new();
    for pair in &sla_rows {
        if pair.origin_id.trim().is_empty()
            || pair.dest_id.trim().is_empty()
            || pair.market_class.trim().is_empty()
            || pair.required_stops.trim().is_empty()
            || pair.evidence_basis.trim().is_empty()
        {
            anyhow::bail!("{} has incomplete SLA pair contract", pair.pair_id);
        }
        if !matches!(pair.target_hours.round() as u16, 36 | 48) {
            anyhow::bail!(
                "{} has unsupported T1 target_hours {}; T1 promises must be 36h or 48h",
                pair.pair_id,
                pair.target_hours
            );
        }
        for route in pair.required_routes.split(';') {
            let route = normalise_designation(route.trim());
            if !route.is_empty() {
                required_route_pairs
                    .entry(route.clone())
                    .or_default()
                    .push(pair.pair_id.clone());
                required_route_priority
                    .entry(route)
                    .and_modify(|priority| *priority = (*priority).max(pair.priority))
                    .or_insert(pair.priority);
            }
        }
    }
    tier_rows.sort_by(|a, b| {
        let a_route = normalise_designation(&a.route);
        let b_route = normalise_designation(&b.route);
        let (_, _, _, _, a_penalty, _, _) =
            constraint_budget_for_candidate(&a_route, "", &constraint_budget_index);
        let (_, _, _, _, b_penalty, _, _) =
            constraint_budget_for_candidate(&b_route, "", &constraint_budget_index);
        let a_adjusted_score = a.score - a_penalty;
        let b_adjusted_score = b.score - b_penalty;
        required_route_priority
            .get(&b_route)
            .unwrap_or(&0)
            .cmp(required_route_priority.get(&a_route).unwrap_or(&0))
            .then_with(|| b_adjusted_score.total_cmp(&a_adjusted_score))
            .then_with(|| b.score.total_cmp(&a.score))
            .then_with(|| a_route.cmp(&b_route))
    });

    let mut stop_rows = csv::Reader::from_path(stop_candidates)
        .with_context(|| format!("reading {}", stop_candidates.display()))?
        .deserialize::<StopCandidateRow>()
        .collect::<Result<Vec<_>, _>>()
        .with_context(|| format!("parsing {}", stop_candidates.display()))?;
    stop_rows.sort_by(|a, b| {
        stop_candidate_selector_score(b)
            .cmp(&stop_candidate_selector_score(a))
            .then_with(|| a.name.cmp(&b.name))
    });
    let top_city_ids = stop_rows
        .iter()
        .take(city_budget)
        .map(|row| row.stop_id.clone())
        .collect::<std::collections::BTreeSet<_>>();

    let mut remaining_stop_budget = stop_budget;
    let mut selected_routes = 0usize;
    let mut rows = Vec::new();
    for (idx, row) in tier_rows.iter().enumerate() {
        let route = normalise_designation(&row.route);
        let route_stops = stop_rows
            .iter()
            .filter(|stop| {
                stop_candidate_routes(stop)
                    .iter()
                    .any(|item| item == &route)
            })
            .collect::<Vec<_>>();
        let top_city_stops = route_stops
            .iter()
            .filter(|stop| top_city_ids.contains(&stop.stop_id))
            .map(|stop| stop.stop_id.as_str())
            .collect::<Vec<_>>();
        let route_sla_pairs = required_route_pairs
            .get(&route)
            .cloned()
            .unwrap_or_default();
        let sla_pair_count = route_sla_pairs.len();
        let is_t1 = row.tier.trim().eq_ignore_ascii_case("T1");
        let score_exception_demoted = sla_pair_count == 0 && demoted_score_routes.contains(&route);
        let score_exception_decision = if sla_pair_count == 0 {
            score_exception_decisions.get(&route).map(String::as_str)
        } else {
            None
        };
        let score_exception_kept =
            matches!(score_exception_decision, Some("keep" | "conditional_keep"));
        let (
            hard_blocker_count,
            claim_blocker_count,
            constraint_debt_cost_m,
            lifecycle_debt_cost_m,
            constraint_penalty_score,
            top_constraint_classes,
            constraint_ledger_artifact,
        ) = constraint_budget_for_candidate(&route, "", &constraint_budget_index);
        let constraint_adjusted_score = row.score - constraint_penalty_score;
        let has_budget =
            selected_routes < route_budget && route_stops.len() <= remaining_stop_budget;
        let selected = (sla_pair_count > 0 || (is_t1 && score_exception_kept)) && has_budget;
        let decision = if selected {
            "select"
        } else if sla_pair_count > 0 {
            "reject-sla-budget"
        } else if score_exception_demoted {
            "reject-score-exception"
        } else if !is_t1 {
            "reject-tier"
        } else if selected_routes >= route_budget {
            "reject-route-budget"
        } else {
            "reject-stop-budget"
        };
        let reason = if selected {
            if sla_pair_count > 0 {
                "sla-required-budget-fit"
            } else if score_exception_decision == Some("keep") {
                "score-exception-keep"
            } else if score_exception_kept {
                "score-exception-conditional-keep"
            } else {
                "score-ranked-budget-fit"
            }
        } else if sla_pair_count > 0 {
            "sla-required-budget-exhausted"
        } else if score_exception_demoted {
            "score-exception-demoted"
        } else if !is_t1 {
            "not-t1-score-band"
        } else if selected_routes >= route_budget {
            "route-budget-exhausted"
        } else {
            "stop-budget-exhausted"
        };
        if selected {
            selected_routes += 1;
            remaining_stop_budget = remaining_stop_budget.saturating_sub(route_stops.len());
        }
        rows.push(T1LineSelectorRow {
            route,
            tier: row.tier.clone(),
            score: row.score,
            constraint_adjusted_score,
            rank: idx + 1,
            selected,
            selected_stop_count: route_stops.len(),
            top_city_stop_count: top_city_stops.len(),
            sla_pair_count,
            budget_cost: route_stops.len(),
            hard_blocker_count,
            claim_blocker_count,
            constraint_debt_cost_m,
            lifecycle_debt_cost_m,
            constraint_penalty_score,
            top_constraint_classes,
            constraint_ledger_artifact,
            decision,
            reason,
            selected_stops: route_stops
                .iter()
                .map(|stop| stop.stop_id.as_str())
                .collect::<Vec<_>>()
                .join(";"),
            top_city_stops: top_city_stops.join(";"),
            sla_pairs: route_sla_pairs.join(";"),
        });
    }
    Ok(rows)
}

fn build_t1_line_selector_csv(rows: &[T1LineSelectorRow]) -> String {
    let mut csv = String::from(
        "route,tier,score,constraint_adjusted_score,rank,selected,selected_stop_count,top_city_stop_count,sla_pair_count,budget_cost,hard_blocker_count,claim_blocker_count,constraint_debt_cost_m,lifecycle_debt_cost_m,constraint_penalty_score,top_constraint_classes,constraint_ledger_artifact,decision,reason,selected_stops,top_city_stops,sla_pairs\n",
    );
    for row in rows {
        push_csv_line(
            &mut csv,
            &[
                &row.route,
                &row.tier,
                &format!("{:.1}", row.score),
                &format!("{:.1}", row.constraint_adjusted_score),
                &row.rank.to_string(),
                if row.selected { "true" } else { "false" },
                &row.selected_stop_count.to_string(),
                &row.top_city_stop_count.to_string(),
                &row.sla_pair_count.to_string(),
                &row.budget_cost.to_string(),
                &row.hard_blocker_count.to_string(),
                &row.claim_blocker_count.to_string(),
                &format!("{:.2}", row.constraint_debt_cost_m),
                &format!("{:.2}", row.lifecycle_debt_cost_m),
                &format!("{:.2}", row.constraint_penalty_score),
                &row.top_constraint_classes,
                &row.constraint_ledger_artifact,
                row.decision,
                row.reason,
                &row.selected_stops,
                &row.top_city_stops,
                &row.sla_pairs,
            ],
        );
    }
    csv
}

fn push_csv_line(csv: &mut String, cells: &[&str]) {
    for (idx, cell) in cells.iter().enumerate() {
        if idx > 0 {
            csv.push(',');
        }
        let needs_quotes = cell.contains(',') || cell.contains('"') || cell.contains('\n');
        if needs_quotes {
            csv.push('"');
            csv.push_str(&cell.replace('"', "\"\""));
            csv.push('"');
        } else {
            csv.push_str(cell);
        }
    }
    csv.push('\n');
}

fn t1_line_selector_gate_failures(
    rows: &[T1LineSelectorRow],
    route_budget: usize,
    stop_budget: usize,
) -> Vec<String> {
    let selected = rows.iter().filter(|row| row.selected).collect::<Vec<_>>();
    let mut failures = Vec::new();
    if selected.is_empty() {
        failures.push("no T1 routes selected".to_string());
    }
    if selected.len() > route_budget {
        failures.push(format!(
            "selected {} routes over budget {route_budget}",
            selected.len()
        ));
    }
    let stop_refs = selected
        .iter()
        .map(|row| row.selected_stop_count)
        .sum::<usize>();
    if stop_refs > stop_budget {
        failures.push(format!(
            "selected {stop_refs} stop refs over budget {stop_budget}"
        ));
    }
    for row in rows
        .iter()
        .filter(|row| row.sla_pair_count > 0 && !row.selected)
    {
        failures.push(format!(
            "{} is required by SLA pair(s) {} but was not selected",
            row.route, row.sla_pairs
        ));
    }
    for row in rows {
        if row.constraint_debt_cost_m < 0.0 {
            failures.push(format!("{} has negative constraint debt cost", row.route));
        }
        if row.lifecycle_debt_cost_m < 0.0 {
            failures.push(format!("{} has negative lifecycle debt cost", row.route));
        }
        if row.constraint_penalty_score < 0.0 {
            failures.push(format!("{} has negative constraint penalty", row.route));
        }
        if (row.hard_blocker_count > 0
            || row.claim_blocker_count > 0
            || row.constraint_debt_cost_m > 0.0
            || row.lifecycle_debt_cost_m > 0.0
            || row.constraint_penalty_score > 0.0)
            && (row.top_constraint_classes.trim().is_empty()
                || row.constraint_ledger_artifact.trim().is_empty())
        {
            failures.push(format!(
                "{} has constraint pressure without class summary and ledger artifact",
                row.route
            ));
        }
        if row.selected
            && row.hard_blocker_count > 0
            && !matches!(
                row.reason,
                "sla-required-budget-fit"
                    | "score-ranked-budget-fit"
                    | "score-exception-keep"
                    | "score-exception-conditional-keep"
            )
        {
            failures.push(format!(
                "{} selected with hard blockers but without explicit selector reason",
                row.route
            ));
        }
    }
    failures
}

fn load_t1_line_selector(path: &Path) -> Result<Vec<T1LineSelectorInputRow>> {
    let mut reader = csv::Reader::from_path(path)?;
    let mut rows = Vec::new();
    for row in reader.deserialize() {
        rows.push(row?);
    }
    Ok(rows)
}

fn t1_stop_selector_rows(
    selector_rows: &[T1LineSelectorInputRow],
    stop_rows: &[StopCandidateRow],
    target_regions: usize,
) -> Result<Vec<T1StopSelectorRow>> {
    if target_regions == 0 {
        anyhow::bail!("target_regions must be >= 1");
    }
    let mut rows = Vec::new();
    for selector in selector_rows.iter().filter(|row| row.selected) {
        let route = normalise_designation(&selector.route);
        let selected_ids = selector
            .selected_stops
            .split(';')
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .collect::<std::collections::BTreeSet<_>>();
        let mut route_stops = stop_rows
            .iter()
            .filter(|stop| selected_ids.contains(stop.stop_id.as_str()))
            .filter(|stop| {
                stop_candidate_routes(stop)
                    .iter()
                    .any(|candidate| candidate == &route)
            })
            .collect::<Vec<_>>();
        sort_stops_for_route(&mut route_stops);
        if route_stops.is_empty() {
            anyhow::bail!("{route}: selected route has no stop candidates");
        }
        let region_count = target_regions.min(route_stops.len());
        let weights = route_stops
            .iter()
            .map(|stop| i32::from(stop_candidate_selector_score(stop).max(1)))
            .collect::<Vec<_>>();
        let input = route_network::LinearRouteSplitInput::with_weights(
            route_network::LinearRouteSplitObjective::HybridService,
            weights.clone(),
        )
        .map_err(|err| anyhow::anyhow!(err))?;
        let regions = route_network::linear_route_stop_regions_with_input(&input, region_count)
            .map_err(|err| anyhow::anyhow!("{route}: {err}"))?;
        let split_stops = route_network::linear_route_split_stops_with_input(&input, region_count)
            .map_err(|err| anyhow::anyhow!("{route}: {err}"))?;
        let mut region_by_stop = vec![0usize; route_stops.len()];
        for region in regions {
            for idx in region.start_stop_index..=region.end_stop_index {
                region_by_stop[idx] = region.region_index;
            }
        }
        let boundary_after = split_stops
            .iter()
            .map(|split| split.before_stop_index)
            .collect::<std::collections::BTreeSet<_>>();
        for (idx, stop) in route_stops.iter().enumerate() {
            rows.push(T1StopSelectorRow {
                route: route.clone(),
                stop_sequence: idx + 1,
                stop_id: stop.stop_id.clone(),
                stop_name: stop.name.clone(),
                requested_class: stop.requested_class.clone(),
                selector_weight: weights[idx],
                split_objective: route_network::LinearRouteSplitObjective::HybridService
                    .mode_name()
                    .to_string(),
                target_regions: region_count,
                metis_region: region_by_stop[idx],
                boundary_after: boundary_after.contains(&idx),
                evidence_status: stop.evidence_status.clone(),
                validation_status: "pass".to_string(),
            });
        }
    }
    Ok(rows)
}

fn write_t1_stop_selector(path: &Path, rows: &[T1StopSelectorRow]) -> Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("creating {}", parent.display()))?;
    }
    let mut writer = csv::Writer::from_path(path)?;
    for row in rows {
        writer.serialize(row)?;
    }
    writer.flush()?;
    Ok(())
}

fn print_t1_stop_selector_summary(output: &Path, rows: &[T1StopSelectorRow]) {
    let route_count = rows
        .iter()
        .map(|row| row.route.as_str())
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let boundary_count = rows.iter().filter(|row| row.boundary_after).count();
    println!(
        "  wrote {} stop rows across {} T1 routes to {}",
        rows.len(),
        route_count,
        output.display()
    );
    println!("  METIS split boundaries: {boundary_count}");
}

fn t1_stop_selector_gate_failures(rows: &[T1StopSelectorRow]) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T1 stop selector rows emitted".to_string());
        return failures;
    }
    let mut by_route = std::collections::BTreeMap::<&str, Vec<&T1StopSelectorRow>>::new();
    for row in rows {
        by_route.entry(row.route.as_str()).or_default().push(row);
        if row.selector_weight <= 0 {
            failures.push(format!(
                "{}:{} has non-positive selector weight",
                row.route, row.stop_id
            ));
        }
        if !row.validation_status.eq_ignore_ascii_case("pass") {
            failures.push(format!(
                "{}:{} has validation_status={}",
                row.route, row.stop_id, row.validation_status
            ));
        }
    }
    for (route, route_rows) in by_route {
        if route_rows.len() < 3 {
            failures.push(format!("{route}: fewer than 3 selected stops"));
        }
        let regions = route_rows
            .iter()
            .map(|row| row.metis_region)
            .collect::<std::collections::BTreeSet<_>>();
        if regions.len() != route_rows[0].target_regions {
            failures.push(format!(
                "{route}: expected {} METIS regions, found {}",
                route_rows[0].target_regions,
                regions.len()
            ));
        }
    }
    failures
}

