fn stop_candidate_gate_failures(rows: &[&StopCandidateRow]) -> Vec<String> {
    let mut failures = Vec::new();
    for row in rows {
        let id = row.stop_id.trim();
        let class = row.requested_class.trim().to_ascii_uppercase();
        let routes = stop_candidate_routes(row);
        if id.is_empty() {
            failures.push("row missing stop_id".to_string());
        }
        if row.name.trim().is_empty() {
            failures.push(format!("{id}: missing name"));
        }
        if !matches!(class.as_str(), "S1" | "S2" | "S3" | "S4" | "S5") {
            failures.push(format!(
                "{id}: unsupported requested_class {}",
                row.requested_class
            ));
        }
        if routes.is_empty() {
            failures.push(format!("{id}: missing route_refs"));
        }
        if row.stop_role.trim().is_empty() {
            failures.push(format!("{id}: missing stop_role"));
        }
        if row.source_artifact.trim().is_empty() {
            failures.push(format!("{id}: missing source_artifact"));
        }
        if row.next_step.trim().is_empty() {
            failures.push(format!("{id}: missing next_step"));
        }
        if !valid_stop_evidence_status(&row.evidence_status) {
            failures.push(format!(
                "{id}: unsupported evidence_status {}",
                row.evidence_status
            ));
        }

        if matches!(class.as_str(), "S1" | "S2") {
            let role = row.stop_role.to_ascii_lowercase();
            let has_terminal_role = role.contains("national_terminal")
                || role.contains("major_interchange_hub")
                || role.contains("port_gateway")
                || role.contains("intermodal_gateway");
            let one_route_terminal = class == "S1"
                && role.contains("national_terminal")
                && (role.contains("border_gateway") || role.contains("port_gateway"));
            if !has_terminal_role {
                failures.push(format!(
                    "{id}: {class} needs national_terminal, major_interchange_hub, port_gateway, or intermodal_gateway role"
                ));
            }
            if routes.len() < 2 && !one_route_terminal {
                failures.push(format!("{id}: {class} needs at least two route_refs"));
            }
            if !high_or_medium(&row.transfer_value)
                && !high_or_medium(&row.freight_volume)
                && !high_or_medium(&row.resilience_value)
            {
                failures.push(format!(
                    "{id}: {class} needs medium/high transfer, freight, or resilience value"
                ));
            }
        }

        if class == "S3"
            && routes.len() < 2
            && !row.stop_role.to_ascii_lowercase().contains("transfer")
        {
            failures.push(format!(
                "{id}: S3 needs a transfer role or at least two route_refs"
            ));
        }

        if class == "S4" && row.spacing_need.trim().is_empty() {
            failures.push(format!("{id}: S4 needs spacing_need evidence"));
        }
    }
    failures
}

fn valid_stop_evidence_status(status: &str) -> bool {
    matches!(
        status.trim().to_ascii_lowercase().as_str(),
        "validated"
            | "heuristic"
            | "planned"
            | "partial"
            | "source_needed"
            | "missing_source"
            | "missing_graph_data"
    )
}

fn high_or_medium(value: &str) -> bool {
    matches!(
        value.trim().to_ascii_lowercase().as_str(),
        "high" | "medium" | "met"
    )
}

fn print_tier_connectivity(
    tier: &str,
    rows: &[route_network::TierConnectivityRow],
    exceptions: &[EndpointExceptionRow],
    details: bool,
) {
    let mut by_class = std::collections::BTreeMap::new();
    for row in rows {
        *by_class
            .entry(row.classification.as_str().to_string())
            .or_insert(0usize) += 1;
    }
    let failures = tier_connectivity_gate_failures_with_exceptions(rows, exceptions, tier);

    println!("  tier: {tier}");
    println!("  routes analyzed: {}", rows.len());
    println!("  node class mix: {}", format_count_map(&by_class));
    println!("  gate blockers: {}", failures.len());
    println!();
    println!(
        "{:<10} {:>7} {:>8} {:>7} {:<18} {:<28} T1 trunks",
        "Route", "Miles", "T1 nodes", "T1s", "Class", "Endpoint exception"
    );
    println!("{}", "-".repeat(124));
    for row in rows {
        println!(
            "{:<10} {:>7.0} {:>8} {:>7} {:<18} {:<28} {}",
            row.route,
            row.route_miles,
            row.t1_node_count,
            row.t1_routes.len(),
            row.classification.as_str(),
            truncate_for_table(
                &endpoint_exception_summary(exceptions, &row.route, tier),
                28
            ),
            if row.t1_routes.is_empty() {
                "-".to_string()
            } else {
                row.t1_routes.join(",")
            }
        );
        if details {
            for touch in &row.touch_nodes {
                println!(
                    "  node {:>8}: {:>8.3},{:>7.3} via {}",
                    touch.node_id,
                    touch.lon,
                    touch.lat,
                    touch.t1_routes.join(",")
                );
            }
        }
    }

    if !failures.is_empty() {
        println!();
        println!(
            "  interpretation: {} rows look like one-ended feeders, local spurs, or missing graph data.",
            failures.len()
        );
        println!(
            "  use these as demotion candidates, graph-contact fixes, or terminal-worthy exception records."
        );
    }
}

fn print_bridge_standard_coverage(
    tier: &str,
    routes: &[String],
    nbi: &std::collections::HashMap<String, NbiBridgeRecord>,
    details: bool,
) {
    let covered = routes
        .iter()
        .filter(|route| nbi.contains_key(*route))
        .count();
    let total_bridges: u32 = routes
        .iter()
        .filter_map(|route| nbi.get(route))
        .map(|row| row.bridge_count)
        .sum();
    let total_poor: f32 = routes
        .iter()
        .filter_map(|route| nbi.get(route))
        .map(|row| row.pct_bridges_poor * row.bridge_count as f32)
        .sum();
    let poor_pct = if total_bridges > 0 {
        total_poor / total_bridges as f32
    } else {
        0.0
    };
    let missing = bridge_standard_missing_routes(routes, nbi);

    println!("route standards-bridges");
    println!("  tier: {tier}");
    println!("  routes: {}", routes.len());
    println!("  routes with NBI coverage: {covered}");
    println!("  total bridges: {total_bridges}");
    println!("  poor/critical bridge share: {:.2}%", poor_pct * 100.0);
    println!("  missing coverage: {}", missing.len());
    println!("  note: clearance and load-posting joins remain separate source gaps");

    if details {
        println!();
        println!(
            "{:<10} {:>8} {:>9} {:>10}",
            "Route", "Bridges", "Poor %", "Mean Year"
        );
        println!("{}", "-".repeat(44));
        for route in routes {
            if let Some(row) = nbi.get(route) {
                println!(
                    "{:<10} {:>8} {:>8.2}% {:>10.0}",
                    route,
                    row.bridge_count,
                    row.pct_bridges_poor * 100.0,
                    row.mean_year_built
                );
            } else {
                println!("{:<10} {:>8} {:>9} {:>10}", route, "-", "-", "-");
            }
        }
    }
}

fn bridge_standard_missing_routes(
    routes: &[String],
    nbi: &std::collections::HashMap<String, NbiBridgeRecord>,
) -> Vec<String> {
    routes
        .iter()
        .filter(|route| !nbi.contains_key(*route))
        .cloned()
        .collect()
}

#[derive(Debug, Clone, serde::Deserialize)]
struct PressureScenarioRow {
    scenario_id: String,
    scenario_name: String,
    adversity_class: String,
    standards_tested: String,
    current_status: String,
    existing_artifact: String,
    blocking_gap: String,
    next_evidence_step: String,
}

fn load_pressure_scenarios(path: &Path) -> Result<Vec<PressureScenarioRow>> {
    let file = std::fs::File::open(path)?;
    parse_pressure_scenarios(file)
}

fn parse_pressure_scenarios<R: std::io::Read>(reader: R) -> Result<Vec<PressureScenarioRow>> {
    let mut rdr = csv::Reader::from_reader(reader);
    let mut rows = Vec::new();
    for result in rdr.deserialize() {
        rows.push(result?);
    }
    Ok(rows)
}

fn print_pressure_scenarios(rows: &[PressureScenarioRow], blockers: bool, details: bool) {
    let failures = pressure_scenario_gate_failures(rows);
    let filtered = if blockers {
        failures.clone()
    } else {
        rows.iter().collect::<Vec<_>>()
    };
    let mut by_status: std::collections::BTreeMap<String, usize> =
        std::collections::BTreeMap::new();
    for row in rows {
        *by_status.entry(row.current_status.clone()).or_insert(0) += 1;
    }

    println!("route pressure-scenarios");
    println!(
        "  scenarios: {} shown / {} total",
        filtered.len(),
        rows.len()
    );
    println!("  status: {}", format_count_map(&by_status));
    println!("  L2 gate blockers: {}", failures.len());
    println!();
    println!(
        "{:<18} {:<24} {:<14} {:<28} {}",
        "Scenario", "Name", "Status", "Adversity", "Gap"
    );
    println!("{}", "-".repeat(132));
    for row in filtered {
        println!(
            "{:<18} {:<24} {:<14} {:<28} {}",
            row.scenario_id,
            truncate_for_table(&row.scenario_name, 24),
            row.current_status,
            truncate_for_table(&row.adversity_class, 28),
            row.blocking_gap
        );
        if details {
            println!("  standards: {}", row.standards_tested);
            println!("  artifact: {}", row.existing_artifact);
            println!("  next: {}", row.next_evidence_step);
        }
    }
}

fn pressure_scenario_gate_failures(rows: &[PressureScenarioRow]) -> Vec<&PressureScenarioRow> {
    rows.iter()
        .filter(|row| !pressure_scenario_has_bounded_contract(row))
        .collect()
}

fn pressure_scenario_readiness_gate_failures(
    rows: &[PressureScenarioRow],
) -> Vec<&PressureScenarioRow> {
    rows.iter()
        .filter(|row| !pressure_scenario_is_executable(row))
        .collect()
}

fn pressure_scenario_missing_required_adversity(rows: &[PressureScenarioRow]) -> Vec<&'static str> {
    const REQUIRED: &[(&str, &[&str])] = &[
        ("T1/T1 closure", &["t1/t1"]),
        ("corridor segment closure", &["corridor segment", "closure"]),
        ("port surge", &["port surge"]),
        ("weather/flood disruption", &["weather", "flood"]),
        ("relay hub outage", &["relay hub outage"]),
        ("EV/rest-area outage", &["ev/rest-area outage"]),
        ("managed-lane sensitivity", &["managed-lane"]),
    ];

    REQUIRED
        .iter()
        .filter_map(|(label, terms)| {
            let covered = rows.iter().any(|row| {
                let class = row.adversity_class.to_ascii_lowercase();
                if *label == "weather/flood disruption" {
                    terms.iter().any(|term| class.contains(term))
                } else {
                    terms.iter().all(|term| class.contains(term))
                }
            });
            (!covered).then_some(*label)
        })
        .collect()
}

fn print_pressure_standard_coverage(
    standards: &[StandardsProofRow],
    scenarios: &[PressureScenarioRow],
) {
    let scenario_refs = pressure_standard_scenario_refs(scenarios);
    let focus = pressure_standard_coverage_focus(standards);
    let failures = pressure_standard_coverage_failures(standards, scenarios);
    let unknown = pressure_scenario_unknown_standard_refs(standards, scenarios);

    println!();
    println!("Pressure standard coverage");
    println!(
        "  high-stakes T1 throughput/resilience standards: {}",
        focus.len()
    );
    println!(
        "  scenario-covered: {}",
        focus
            .iter()
            .filter(|row| scenario_refs.contains_key(row.standard_id.as_str()))
            .count()
    );
    println!("  missing hooks: {}", failures.len());
    println!("  unknown refs: {}", unknown.len());
    println!();
    println!(
        "{:<22} {:<12} {:<8} {:<22} {}",
        "Standard", "Family", "Evidence", "Scenario", "Stressor"
    );
    println!("{}", "-".repeat(112));
    for row in focus {
        let scenario = scenario_refs
            .get(row.standard_id.as_str())
            .map(|ids| ids.join("; "))
            .unwrap_or_else(|| "missing".to_string());
        println!(
            "{:<22} {:<12} {:<8} {:<22} {}",
            row.standard_id,
            row.standard_family,
            row.evidence_level,
            truncate_for_table(&scenario, 22),
            row.primary_stressor
        );
    }
    if !unknown.is_empty() {
        println!();
        println!("  unknown scenario standard refs: {}", unknown.join(", "));
    }
}

fn pressure_standard_coverage_failures<'a>(
    standards: &'a [StandardsProofRow],
    scenarios: &[PressureScenarioRow],
) -> Vec<&'a StandardsProofRow> {
    let scenario_refs = pressure_standard_scenario_refs(scenarios);
    pressure_standard_coverage_focus(standards)
        .into_iter()
        .filter(|row| !scenario_refs.contains_key(row.standard_id.as_str()))
        .collect()
}

fn pressure_standard_coverage_focus(standards: &[StandardsProofRow]) -> Vec<&StandardsProofRow> {
    standards
        .iter()
        .filter(|row| {
            row.tier == "T1"
                && matches!(row.standard_family.as_str(), "throughput" | "resilience")
                && !row.evidence_level.eq_ignore_ascii_case("deprecated")
        })
        .collect()
}

fn pressure_scenario_unknown_standard_refs(
    standards: &[StandardsProofRow],
    scenarios: &[PressureScenarioRow],
) -> Vec<String> {
    let known = standards
        .iter()
        .map(|row| row.standard_id.as_str())
        .collect::<std::collections::BTreeSet<_>>();
    let mut unknown = pressure_standard_scenario_refs(scenarios)
        .keys()
        .filter(|standard_id| !known.contains(**standard_id))
        .map(|standard_id| (*standard_id).to_string())
        .collect::<Vec<_>>();
    unknown.sort();
    unknown
}

fn pressure_standard_scenario_refs(
    scenarios: &[PressureScenarioRow],
) -> std::collections::BTreeMap<&str, Vec<String>> {
    let mut refs = std::collections::BTreeMap::new();
    for row in scenarios {
        for standard_id in row
            .standards_tested
            .split(';')
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            refs.entry(standard_id)
                .or_insert_with(Vec::new)
                .push(row.scenario_id.clone());
        }
    }
    refs
}

fn pressure_scenario_is_executable(row: &PressureScenarioRow) -> bool {
    matches!(
        row.current_status.trim().to_ascii_lowercase().as_str(),
        "implemented" | "heuristic"
    )
}

fn pressure_scenario_has_bounded_contract(row: &PressureScenarioRow) -> bool {
    let has_identity = row.scenario_id.starts_with("S-L2-")
        && !row.scenario_name.trim().is_empty()
        && !row.adversity_class.trim().is_empty();
    let has_test_scope = !row.standards_tested.trim().is_empty()
        && row
            .standards_tested
            .split(';')
            .any(|value| value.trim().starts_with('T'));
    let has_artifact = !row.existing_artifact.trim().is_empty();
    let has_next_step = !row.next_evidence_step.trim().is_empty();
    let status = row.current_status.to_ascii_lowercase();
    let status_is_labeled = matches!(
        status.as_str(),
        "implemented" | "heuristic" | "planned" | "stub" | "deprecated"
    );

    has_identity && has_test_scope && has_artifact && has_next_step && status_is_labeled
}

